        private static string Class(int Class)
        {
            if (Class == 15) { return "Trojan"; }
            if (Class == 25) { return "Warrior"; }
            if (Class == 45) { return "Archer"; }
            if (Class == 55) { return "Ninja"; }
            if (Class == 65) { return "Monk"; }
            if (Class == 75) { return "Pirate"; }
            if (Class == 85) { return "Dragon-Warrior"; }
            if (Class == 165) { return "Wind-Walker"; }
            if (Class == 135) { return "WaterTaoist"; }
            if (Class == 145) { return "FireTaoist"; }
            if (Class == 0) { return "Not selected"; }
            return "Not selected";

        }
        private static string ATTKs(int ATTKs)
        {
            if (ATTKs == 201) { return "[Strike]+[HP]+[Attack]+[Immy]"; }
            if (ATTKs == 202) { return "[Break]+[HP]+[Attack]+[Immy]"; }
            if (ATTKs == 203) { return "[M-Attack]+[HP]+[M-Strike]+[Immy]"; }
            if (ATTKs == 204) { return "[P-Damge]+[HP]+[AntiBreak]+[Immy]"; }
            if (ATTKs == 0) { return "Not selected"; }
            return "Not selected";

        }
        [NpcAttribute(NpcID.NewTwinNpcs)]
        public static void NewTwinNpcs(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);

            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hello " + client.Player.Name + " I'm here to help you with a few things Without fees")
                        .AddOption("Collect[Book] ", 1)
                      //  .AddOption("BotHunt[Book]", 2)
                        .AddOption("Change Password .", 3)
                        .AddOption("WebSite of Game .", 4)
                        .AddOption("Facebook .", 5)
                        .AddOption("[Time of Hourly Events] .", 6)
                        .AddOption("[Time of Daily Events] .", 7)
                        .AddOption("[Time of Weekly Events] .", 8)
                        .AddOption("Thanks ", 255)
                        .AddAvatar(63).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (!client.Inventory.Contain(3005487, 1, 1))
                        {
                            if (client.Inventory.HaveSpace(1))
                                client.Inventory.AddDIABLO2(3005487, 0, 1, stream, true);
