                        data.AddOption("Later.", 255);
                        data.AddAvatar(255).FinalizeDialog();
                        break;
                    }
                case 31:
                    {
                        try
                        {
                            string oldpass = Input;
                            using (var cmd = new MySqlCommand(MySqlCommandType.SELECT))
