        [NpcAttribute(NpcID.CreateBooth)]
        public static void CreateBooth(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {

            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:


                    if (client.MyBotBooth.booth == null)
                    {
                        if (client.MyBotBooth.oldbooth)
                        {
                            dialog.AddText("Would you like to claim last season's profits and items?.");
                            dialog.Option("Sure", 215);
                        }
                        else
                        {
                            dialog.Text("Hey!! I can help you to create an offline booth to sell your items all day long ...");
                            dialog.Option("Create new booth!", 201);
                        }
                    }
                    else
                    {
                        dialog.Text("Congratulations!! for creating your booth ,The next step is to manage your goods and sales.. ");
                        dialog.Option("Add Items..", 212);
                        dialog.Option("Remove Booth..", 203);
                        dialog.Option("View My Earnings", 204);
                    }


                    dialog.Option("Just passing..", 255);
                    dialog.Send();
                    break;
                #region create booth  201
                case 201:
                    dialog.AddText("Please select ShopFlag.");
                    foreach (var item in BotBoothDB.Shopflags.OrderBy(i => i.Key))
                    {
                        if (Database.Server.ServerMaps[1036].IsValidFlagNpc(item.Value.X, item.Value.Y))
                        {
                            dialog.Option("ShopFlag [" + item.Key + "]", item.Key);
                        }

                    }
                    dialog.Send();
                    break;
                case 220:
                    string boothmess = "None";
                    if (client.MyBotBooth.HawkMessage != null)
                        boothmess = client.MyBotBooth.HawkMessage.__Message;
                    dialog.AddText("ShopFlag [" + client.MyBotBooth.Flag + "]. \n");
                    dialog.AddText("Action [" + client.MyBotBooth.Action.ToString() + "]. \n");
                   // dialog.AddText("HawkMessage [" + boothmess + "]. \n");
                    dialog.Option("Select ShopFlag..", 201);
                    dialog.Option("Record Action..", 221);
                  //  dialog.Option("Add HawkMessage..", 222);
                    dialog.Option("Create Booth..", 225);
                    dialog.Send();
                    break;
                case 221:
                    string action = client.Player.Action.ToString();
                    if (client.Player.Action == Flags.ConquerAction.Jump || client.Player.Action == Flags.ConquerAction.InteractionHold || client.Player.Action == Flags.ConquerAction.InteractionHug || client.Player.Action == Flags.ConquerAction.InteractionKiss || client.Player.Action == Flags.ConquerAction.CoupleDances || client.Player.Action == Flags.ConquerAction.CoupleDances || client.Player.Action == Flags.ConquerAction.MagicDefender)
                        action = "None";
                    dialog.AddText("Your Action is [" + action + "]. \n");
                    dialog.AddText("Make your character do action (sit,cool,dance,bow) then select [Record again]. \n");
                    dialog.AddText("Ex:- (sit,cool,dance,bow) \n");
                    dialog.Option("Select", 223);
                    dialog.Option("Record again", 221);
                    dialog.Send();
                    break;
                case 223:

                    client.MyBotBooth.Action = client.Player.Action;
                    if (client.Player.Action == Flags.ConquerAction.Jump || client.Player.Action == Flags.ConquerAction.InteractionHold || client.Player.Action == Flags.ConquerAction.InteractionHug || client.Player.Action == Flags.ConquerAction.InteractionKiss || client.Player.Action == Flags.ConquerAction.CoupleDances || client.Player.Action == Flags.ConquerAction.CoupleDances || client.Player.Action == Flags.ConquerAction.MagicDefender)
                        client.MyBotBooth.Action = Flags.ConquerAction.None;
                    goto case 220;
                case 222:
                    dialog.AddText("Add hawkmessage message Here..\n");
                    dialog.AddText("Use '+' instead of spaces ' ' \n");
                    dialog.AddText("Ex:  (I+buy+Items.)  XX (I buy Items.) XX\n");
                    dialog.AddText("Ex:  (Selling+Souls+p7+in+shop+37)  XX (Selling Souls p7 in shop 37) XX\n");
                    dialog.AddInput50("Message ", 224);
                    dialog.Send();
                    break;
                case 224:
                    client.MyBotBooth.HawkMessage = new MsgMessage(Input.Replace('+', ' '), "ALL", client.Player.Name + "[Bot]", MsgMessage.MsgColor.yellow, MsgMessage.ChatMode.HawkMessage);
                    goto case 220;
                case 225:
                    client.MyBotBooth.CreateBooth(stream);
                    break;
                #endregion
                #region Controll booth 212 202 215 204 205 203
                #region Additems
                case 212:
                    {
                        dialog.AddText("Enter Item Price..");
                        dialog.AddInput9("Cps ", 202);
                        dialog.Send();
                        break;
                    }

                case 202:
                    client.MyBotBooth.GetItems();
                    if (!uint.TryParse(Input, out client.MyBotBooth.selecteditemprice))
                    {
                        client.MessageBox("Wrong Input ,Please try again");
                        break;
                    }

                    dialog.Text("Select Item to sell ..\n");
                    foreach (var item in client.MyBotBooth.SelectionItems)
                    {
                        var DBItem = Database.Server.ItemsBase[item.Value.ITEM_ID];
                        dialog.Option("" + DBItem.Name + "" + (item.Value.Plus > 0 ? "(+" + item.Value.Plus + ")" : "") + " " + (item.Value.StackSize > 1 ? "X " + item.Value.StackSize + "" : "") + " ", item.Key);
                    }

                    dialog.Send();
                    break;
                #endregion
                #region Oldbooth
                case 215:
                    if (client.MyBotBooth.oldbooth)
                    {
                        if (client.MyBotBooth.OldBotItems.Count > 0)
                        {
                            if (client.Inventory.HaveSpace((byte)client.MyBotBooth.OldBotItems.Count))
                            {
                                foreach (var item in client.MyBotBooth.OldBotItems.Values)
                                    client.Inventory.Update(item, Role.Instance.AddMode.MOVE, stream);

                            }
                            else
                            {
                                client.MessageBox("You must have at least " + client.MyBotBooth.OldBotItems.Count + " empty spaces in your inventory");
                                return;
                            }
                        }
                        client.Player.ConquerPoints += client.MyBotBooth.Profits;
                        client.MyBotBooth.Profits = 0;
                        client.MyBotBooth.oldbooth = false;
                        client.MyBotBooth.OldBotItems.Clear();
                        if (PlayerbotBooth.BotBooths.ContainsKey(client.Player.UID))
                            PlayerbotBooth.BotBooths.Remove(client.Player.UID);
                        client.MessageBox("you have claimed both your profits and remaining items");
                    }
                    break;
                #endregion
                #region Profits
                case 204:
                    dialog.AddText("You have " + client.MyBotBooth.Profits + " Cps.");
                    dialog.Option("Claim Earnings", 205);
                    dialog.Send();
                    break;
                case 205:
                    if (client.MyBotBooth.Profits > 0)
                    {
                        client.MessageBox("you have claimed booth " + client.MyBotBooth.Profits + " Cps");
                        client.Player.ConquerPoints += client.MyBotBooth.Profits;
                        client.MyBotBooth.Profits = 0;

                    }
                    else
                    {
                        client.MessageBox("Sorry,But you have no Earnings");
                    }
                    break;
                case 203:
                    string m = "";
                    if (!client.MyBotBooth.RemoveBooth(out m))
                        client.MessageBox(m);
                    break;
                #endregion
                #endregion
                default:
                    if (client.MyBotBooth.booth != null)
                    {
                        MsgGameItem item;
                        if (client.MyBotBooth.SelectionItems.TryGetValue(Option, out item))
                        {

                            if (client.Inventory.Contain(item.ITEM_ID, item.StackSize))
                            {
                                string e = "";
                                if (client.MyBotBooth.AddItem(item, stream, out e))

                                    client.MessageBox(Database.Server.ItemsBase[item.ITEM_ID].Name + (item.StackSize > 1 ? "X " + item.StackSize + "" : "") + " been added");
                                else
                                    client.MessageBox(e);

                            }
                            else
                            {
                                dialog.AddText("Don't play Jokes on me!!");
                                dialog.Option("Haha,Just kidding..", 255);
                                dialog.Send();
                            }
                        }

                    }
                    else
                    {
                        var coordinate = BotBoothDB.Shopflags[Option];
                        if (Database.Server.ServerMaps[1036].IsValidFlagNpc(coordinate.X, coordinate.Y))
                        {
                            client.MyBotBooth.Flag = Option;
                            goto case 220;
                        }
                    }

                    break;
            }
        }
        public static void CollectBook(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hello " + client.Player.Name + " This Book Help You To Control Which Items You Want Collect It While Hunting if Option Contain [True] It Mean Will Collect It ");
                        if (client.Player.DBCollect == true)
                            data.AddOption("DB-Collect [True]", 2);
                        else
                            data.AddOption("DB-Collect [False]", 2);
                        if (client.Player.MeteorCollect == true)
                            data.AddOption("Meteor-Collect [True]", 3);
                        else
                            data.AddOption("Meteor-Collect [False]", 3);
                        if (client.Player.Exbballcollect == true)
                            data.AddOption("Expball-Collect [True]", 4);
                        else
                            data.AddOption("Expball-Collect [False]", 4);                      
                        data.AddOption("Thanks", 255);
                        data.AddAvatar(4);
                        data.FinalizeDialog();
                        break;
                    }
                case 2:
                    {
                        if (client.Player.DBCollect == true)
                        {
                            client.Player.DBCollect = false;
                            client.CreateBoxDialog("Now You Can`t Collect DB");
                        }
                        else
                        {
                            client.CreateBoxDialog("Now Can Collect DB");
                            client.Player.DBCollect = true;
                        }
                        break;
                    }
                case 3:
                    {
                        if (client.Player.MeteorCollect == true)
                        {
                            client.Player.MeteorCollect = false;
                            client.CreateBoxDialog("Now You Can`t Collect Meteors");

                        }
                        else
                        {
                            client.Player.MeteorCollect = true;
                            client.CreateBoxDialog("Now Can Collect Meteors");
                        }
                        break;
                    }
                case 4:
                    {
                        if (client.Player.Exbballcollect == true)
                        {
                            client.Player.Exbballcollect = false;
                            client.CreateBoxDialog("Now Can`t Collect Expball");
                        }
                        else
                        {
                            client.Player.Exbballcollect = true;
                            client.CreateBoxDialog("Now Can Collect Expball");
                        }
                        break;
                    }              
            }
        }

        public static void AutoHuntOffline(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        if (!Database.Server.GamePoll.ContainsKey((uint)(60000000 + client.Player.UID)))
                        {
                            data.AddText("Hey" + client.Player.Name + " You want to collect CPs without being connected remember that it is for a quantity of time, You Hav ["+client.Player.RacePoints+"] Donate");
                            data.AddOption("Build Bot[1H] For 5 Donate Points.", 1);
                            data.AddOption("Build Bot[5H] For 20 Donate Points.", 10);
                            data.AddOption("Build Bot[12H] For 50 Donate Points", 11);
                            data.AddAvatar(1806).FinalizeDialog();
                        }
                        else
                        {
                            if (Database.Server.GamePoll.ContainsKey((uint)(60000000 + client.Player.UID)))
                            {
                                var bot = Database.Server.GamePoll[(uint)(60000000 + client.Player.UID)];
                                var timer1 = new TimeSpan(bot.MyAI.Timer.Ticks);
                                var Now2 = new TimeSpan(DateTime.Now.Ticks);
                                int days_left = (int)(timer1.TotalDays - Now2.TotalDays);
                                int hour_left = (int)(timer1.TotalHours - Now2.TotalHours);
                                int left_minutes = (int)(timer1.TotalMinutes - Now2.TotalMinutes);
                                int left_Seconds = (int)(timer1.TotalSeconds - Now2.TotalSeconds);
                                data.AddText("Expiry Date Day[" + days_left + "] Hour[" + hour_left + "] Minute[" + left_minutes + "] Second[" + left_Seconds + "] ");
                                if (bot.Player.OnAutoHunt)
                                    data.AddOption("AutoHunt(Stop).", 2);
                                else
                                    data.AddOption("AutoHunt.", 2);
                                data.AddOption("Teleport.", 3);
                                data.AddOption("Bot Informations.", 4);
                                data.AddOption("GetCPs.", 5);
                               // data.AddOption("Delete Bot", 19);
                                data.AddOption("GetBot.", 6);
                                data.AddAvatar(1806);
                                data.FinalizeDialog();
                            }
                        }
                        break;
                    }
                case 19:
                    {
                        var bot = Database.Server.GamePoll[(uint)(60000000 + client.Player.UID)];
                        client.MyAI.Bot = bot;
                        client.MyAI.RemoveingAutoHunt();
                        break;
                    }
                case 1:
                    {
                        if (client.Player.RacePoints >= 5)
                        {
                            client.Player.RacePoints -= 5;
                            DeathWish.Game.AISystem.AIBotHandle.CreateBots(stream, client, 0, 0,0 ,1);
                        }
                        else
                        {
                            client.CreateBoxDialog("You don't have enough Donate Points");
                        }
                        break;
                    }
                case 10:
                    {
                        if (client.Player.RacePoints >= 20)
                        {
                            client.Player.RacePoints -= 20;
                            DeathWish.Game.AISystem.AIBotHandle.CreateBots(stream, client, 0, 0, 0, 5);
                        }
                        else
                        {
                            client.CreateBoxDialog("You don't have enough Donate Points");
                        }
                        break;
                    }
                case 11:
                    {
                        if (client.Player.RacePoints >= 50)
                        {
                            client.Player.RacePoints -= 50;
                            DeathWish.Game.AISystem.AIBotHandle.CreateBots(stream, client, 0, 0,0, 12);
                        }
                        else
                        {
                            client.CreateBoxDialog("You don't have enough Donate Points");
                        }
                        break;
                    }
                case 2:
                    {
                        if (Database.Server.GamePoll.ContainsKey((uint)(60000000 + client.Player.UID)))
                        {
                            var bot = Database.Server.GamePoll[(uint)(60000000 + client.Player.UID)];
                            if (bot.Player.OnAutoHunt)
                                bot.Player.OnAutoHunt = false;
                            else
                                bot.Player.OnAutoHunt = true;
                        }
                        break;
                    }
                case 3:
                    {
                        if (Database.Server.GamePoll.ContainsKey((uint)(60000000 + client.Player.UID)))
                        {
                            var bot = Database.Server.GamePoll[(uint)(60000000 + client.Player.UID)];
                            bot.Teleport(client.Player.X, client.Player.Y, client.Player.Map, client.Player.DynamicID);
                        }
                        break;
                    }
                case 4:
                    {
                        if (Database.Server.GamePoll.ContainsKey((uint)(60000000 + client.Player.UID)))
                        {
                            #region Timers
                            var timer1 = new TimeSpan(client.MyAI.Timer.Ticks);
                            var Now2 = new TimeSpan(DateTime.Now.Ticks);
                            int days_left = (int)(timer1.TotalDays - Now2.TotalDays);
                            int hour_left = (int)(timer1.TotalHours - Now2.TotalHours);
                            int left_minutes = (int)(timer1.TotalMinutes - Now2.TotalMinutes);
                            #endregion
                            var bot = Database.Server.GamePoll[(uint)(60000000 + client.Player.UID)];
                            data.AddText("*****************************************\n");
                            data.AddText("CPs:" + bot.Player.ConquerPoints + "\n");
                            data.AddText("Map:" + bot.Map.Name + "\n");
                            data.AddText("X:" + bot.Player.X + "\n");
                            data.AddText("Y:" + bot.Player.Y + "\n");
                            if (days_left > 0)
                                data.AddText("Your BOT[Auto] will expire in: " + days_left + "\n");
                            else if (hour_left > 0)
                                data.AddText("Your BOT[Auto] will expire in: " + hour_left + " \n");
                            else if (left_minutes > 0)
                                data.AddText("Your BOT[Auto] will expire in: " + left_minutes + "\n");
                            data.AddText("*****************************************\n");
                            data.FinalizeDialog();
                        }
                        break;
                    }
                case 5:
                    {
                        if (Database.Server.GamePoll.ContainsKey((uint)(60000000 + client.Player.UID)))
                        {
                            var bot = Database.Server.GamePoll[(uint)(60000000 + client.Player.UID)];
                            client.Player.ConquerPoints += bot.Player.ConquerPoints;
                            bot.Player.ConquerPoints = 0;
                            client.CreateBoxDialog("done successfully");
                        }
                        break;
                    }
                case 6:
                    {
                        if (Database.Server.GamePoll.ContainsKey((uint)(60000000 + client.Player.UID)))
                        {
                            var bot = Database.Server.GamePoll[(uint)(60000000 + client.Player.UID)];
                            client.Teleport(bot.Player.X, bot.Player.Y, bot.Player.Map, bot.Player.DynamicID);
                        }
                        break;
                    }
            }
        }
        public static void LotteryBoxes(Client.GameClient user, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {

            Dialog data = new Dialog(user, stream);
            switch (Option)
            {

                case 0:
                    {
                        goto case 1;

                    }
                case 1:
                    {

                        if (user.Player.LotteryEntries < Database.Server.Lottery.LotteryEntry(user.Player.VipLevel))
                        {
                            if (user.Inventory.Contain(711504, 3))
                            {
                                user.Player.Achievement.CreateFlaID(10118, user, stream);
                                user.HeroRewards.AddGoal(306);
                                user.Activeness.IncreaseTask(4);
                                user.Activeness.IncreaseTask(16);
                                user.Activeness.IncreaseTask(28);

                                user.Inventory.Remove(711504, 3, stream);

                                user.Player.LotteryEntries++;
                                //reset lottery jade 
                                user.Player.AddJade = 0;



                                user.Player.LotteryItem = Database.Server.Lottery.GenerateLotteryItem(user);

                                user.Send(stream.LotteryCreate(MsgServer.MsgLottery.Action.Show
                                           , (user.Player.LotteryItem.Sockets > 0) ? Role.Flags.Gem.EmptySocket : Role.Flags.Gem.NoSocket
                                           , (user.Player.LotteryItem.Sockets > 1) ? Role.Flags.Gem.EmptySocket : Role.Flags.Gem.NoSocket
                                           , user.Player.LotteryItem.Plus
                                           , user.Player.LotteryItem.Color
                                           , user.Player.AddJade
                                           , user.Player.LotteryItem.ID));

                                Game.MsgServer.MsgStringPacket packet = new Game.MsgServer.MsgStringPacket();
                                packet.ID = MsgStringPacket.StringID.Effect;
                                packet.UID = id;
                                packet.Strings = new string[1] { "lottery" };


                                user.Player.View.SendView(stream.StringPacketCreate(packet), true);



                            }
                            else
                            {
                                data.AddText("You need to pay 3 Small Lottery Tickets to draw from the lottery in the lottery Center.")
                      .AddOption("Oops.", 255)
                      .AddAvatar(0).FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry, your LotteryEntries has finished come tomorrow.")
                               .AddOption("Oops.", 255)
                               .AddAvatar(0).FinalizeDialog();
                        }

                        break;
                    }
            }
        }
      
