                        else
                        {
                            data.AddText("Sorry But You Dont Have ChiToken . ");
                            data.AddOption("I'll think about it!", 255);
                            data.FinalizeDialog();
                            return;
                        }

                        if (client.Player.UpdateChiStage == -1)
                            break;

                        if (Option >= 21 && Option < 40)//dragon
                        {
