        [NpcAttribute(NpcID.RoomByPika)]
        public static void RoomByPika(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.AddText("Hello! Friend [ " + client.Player.Name + " ] Want To Enter To Custom Room Of " + Program.ServerConfig.ServerName + "  .");
                        dialog.AddOption("[FB/SS] Custom.", 1);
                        dialog.AddOption("[Ninja] Custom.", 2);
                        dialog.AddOption("#Thnx .", 255);
                        dialog.AddAvatar(4).FinalizeDialog(); break;
                    }
                case 1:
                    {
                        dialog.AddText("Choose Which Custom You Want To Play [You Must Have 100 Cps To Join].");
                        dialog.AddOption("Custom [ 10 Hit] .", 46);
                        dialog.AddOption("Custom [ 50 Hit] .", 47);
                        dialog.AddOption("#Thnx .", 255);
                        dialog.AddAvatar(4).FinalizeDialog(); break;
                    }
                case 46:
                    {
                        if (client.Player.RightWeaponId != 0)
                        {
                            if (client.Player.ConquerPoints >= 100)
                            {
                                switch (Program.GetRandom.Next(0, 4))
                                {
                                    case 0:
                                        {
                                            client.Teleport(50, 50, 8601);
                                            break;
                                        }
                                    case 1:
                                        {
                                            client.Teleport(40, 60, 8601);
                                            break;
                                        }
                                    case 2:
                                        {
                                            client.Teleport(45, 45, 8601);
                                            break;
                                        }
                                    case 3:
                                        {
                                            client.Teleport(60, 45, 8601);
                                            break;
                                        }
                                }

                                client.Player.ConquerPoints -= 100;
                                client.Player.MisShoot = 0;
                                client.Player.HitShoot = 0;
                                client.Player.Arenapika = 10;
                                client.Player.SendString(stream, MsgStringPacket.StringID.Effect, true, "movego");

                                client.Player.Stamina = 100;

                                client.Player.RemoveFlag(MsgUpdate.Flags.AzureShield);

                                client.Player.RemoveFlag(MsgUpdate.Flags.Ride);

                                client.Player.SetPkMode(Role.Flags.PKMode.PK);

                                MsgSchedules.SendSysMesage("The Player: [ " + client.Player.Name + " ] , Has Joined World of " + Program.ServerConfig.ServerName + " Gaming Go To Fight [ FB/SS Custom Room ]  [ 10 Hit] .", MsgMessage.ChatMode.TopLeft);
                            }
                            else
                            {
