        [NpcAttribute(NpcID.NewPlayer)]
        public static void NewPlayer(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hello [ <tip color=0xff00fa00> " + client.Player.Name + " </tip> ] ,Welcome to [ <tip color=0xff00fa00> EarthQuake </tip> ] , You Can Prepare Your Character in just [ <tip color=0xff00fa00> 4 clicks </tip> ] \n");
                        data.AddText("[ <tip color=0xfff05050> You Want Choose Char. Or Go Twin </tip> ]");
                        data.AddOption("Choose Character.", 1);
                        data.AddOption("Go TwinCity.", 2);
                        data.AddOption("Thanks.", 255);
                        data.AddAvatar(4).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        data.AddText("Hello [ <tip color=0xff00fa00> " + client.Player.Name + " </tip> ] ,Welcome to [ <tip color=0xff00fa00> HORUS </tip> ] , You Can Prepare Your Character in just [ <tip color=0xff00fa00> 4 clicks </tip> ] \n");
                        data.AddText("[ <tip color=0xfff05050> Please Select Your First Character </tip> ]");
