            switch (Option)
            {
                case 0:
                    {

                        data.AddText("Here You Can Make Your Speacial Items HP255 For 100 K  Cps For Each")
                        .AddOption("HP255.", 1)
                        .AddOption("Thanks.", 255)
                        .FinalizeDialog();


                        break;
                    }
                case 1:
                    {
                        data.AddText("Just paying 1M CPs, you`re able to activate the Wuxing Oven and attach 255 HP attribute on specific equipment.")
                            //.AddOption("Garment.", 2)
                       .AddOption("Star~Tower.", 6)
                       .AddOption("Heaven~Fan.", 8)
                       .AddOption("Riding~Crop.", 10)
                       .AddOption("Wing.", 50)
                       .AddOption("RightWeapon.", 70)
                       .AddOption("LeftWeapon.", 72)
                       .AddOption("Thanks.", 255)
                       .FinalizeDialog();

                        break;

                    }
                case 72:
                    {
                        data.AddText("Are you sure you want to pay 100 K CPs to add HP255 attribute to the LeftWeapon?")
