        [NpcAttribute(NpcID.Emperrors)]
        public static void Emperrors(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hey " + client.Player.Name + " Here Emperrors Quest . You Want to join?! [ Even:50 To Even:55 ]");
                        if (Game.MsgTournaments.MsgEmperorWar.Proces == ProcesType.Alive)
                            data.AddOption("Emperrors[Open] .", 5);
                        else
                            data.AddOption("Emperrors[End] .", 170);
                        data.AddOption("Emperrors[Claim] .", 17);


                        //  data.AddOption("[Time War] .", 170);

                        data.AddOption("#Thanks .", 255).AddAvatar(80).FinalizeDialog();
                        break;
                    }
                case 170:
                    {


                        data.AddText("Emperrors Start  [ Even:50] & End [ Even:55 ] .\n");

                        data.AddOption("#Thanks .", 255);
                        data.FinalizeDialog();
                        return;
                    }

                case 5:
                    {
                        if (Game.MsgTournaments.MsgEmperorWar.Proces == ProcesType.Alive)
                        {
                            client.Teleport(95, 110, 6525);
                        }
                        else
                            client.SendSysMesage("Emperros war has ben finished.");
                        break;
                    }
                case 17:
                    {
                        if (Game.MsgTournaments.MsgEmperorWar.Proces == ProcesType.Dead)
                        {
                            if (Game.MsgTournaments.MsgEmperorWar.RoundOwner != null)
                            {
                                if (Game.MsgTournaments.MsgEmperorWar.RoundOwner.UID == client.Player.UID)
                                {
                                    client.Player.ConquerPoints += 7000;
                                    client.Inventory.Add(stream, 3009003, 1);
