        [NpcAttribute(NpcID.GuildPole)]
        public static void GuildPole(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hi, I'm the leader of GuildPoleRank.");
                        data.AddOption("Join", 1);
                        data.AddOption("Reward", 2);
                        data.AddOption("Thanks");
                        data.AddAvatar(63).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (Game.MsgTournaments.MsgGuildPole.Proces == ProcesType.Alive)
                        {
                            client.Teleport(48, 64, 26400);
                        }
                        else
                        {
                            data.AddText("GuildPoleRank War has ben finished .. Please come back later at hour 01:31 End 02:00 ").AddOption("Alright.").FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        if (Game.MsgTournaments.MsgGuildPole.Proces == ProcesType.Dead)
                        {
                            if (Game.MsgTournaments.MsgGuildPole.RoundOwner != null)
                            {
                                if (Game.MsgTournaments.MsgGuildPole.RoundOwner.UID == client.Player.UID)
                                {
                                    client.Player.ConquerPoints += 50000;
                                    client.Player.Money += 1000000;
                                    client.Player.PIKAPoint += 5;
                                    client.Player.BoundConquerPoints += 100;
                                    client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.Money);
                                    client.Player.SendUpdate(stream, client.Player.ConquerPoints, MsgUpdate.DataType.ConquerPoints);
                                    client.Player.SendUpdate(stream, client.Player.BoundConquerPoints, MsgUpdate.DataType.BoundConquerPoints);
                                    MsgSchedules.SendSysMesage("Congratulations, " + client.Player.Name + " has claim his reward from GuildPoleRank[DeputyLeader] [ 5K Cps +1M Gold + 5EP +100 Coins]", MsgMessage.ChatMode.Center);
                                    Game.MsgTournaments.MsgGuildPole.RoundOwner = null;
                                }
                                else
                                    data.AddText("There is no any rewards now..").AddOption("Alright.").FinalizeDialog();
                            }
                        }
                        if (Game.MsgTournaments.MsgGuildPole1.Proces == ProcesType.Dead)
                        {
                            if (Game.MsgTournaments.MsgGuildPole1.RoundOwner != null)
                            {
                                if (Game.MsgTournaments.MsgGuildPole1.RoundOwner.UID == client.Player.UID)
                                {
                                    client.Player.ConquerPoints += 10000;
                                    client.Player.Money += 2000000;
                                    client.Player.PIKAPoint += 10;
                                    client.Player.BoundConquerPoints += 200;
                                    client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.Money);
                                    client.Player.SendUpdate(stream, client.Player.ConquerPoints, MsgUpdate.DataType.ConquerPoints);
                                    client.Player.SendUpdate(stream, client.Player.BoundConquerPoints, MsgUpdate.DataType.BoundConquerPoints);
                                    MsgSchedules.SendSysMesage("Congratulations, " + client.Player.Name + " has claim his reward from GuildPoleRank[GuildLeader] [ 10K Cps +2M Gold + 10EP +200 Coins]", MsgMessage.ChatMode.Center);
                                    Game.MsgTournaments.MsgGuildPole1.RoundOwner = null;
                                }
                                else
                                    data.AddText("There is no any rewards now..").AddOption("Alright.").FinalizeDialog();
                            }
                        }
                        if (Game.MsgTournaments.MsgGuildPole2.Proces == ProcesType.Dead)
                        {
                            if (Game.MsgTournaments.MsgGuildPole2.RoundOwner != null)
                            {
                                if (Game.MsgTournaments.MsgGuildPole2.RoundOwner.UID == client.Player.UID)
                                {
                                    client.Player.ConquerPoints += 1000;
                                    client.Player.Money += 200000;
                                    client.Player.PIKAPoint += 2;
                                    client.Player.BoundConquerPoints += 50;
                                    client.Player.SendUpdate(stream, client.Player.Money, MsgUpdate.DataType.Money);
                                    client.Player.SendUpdate(stream, client.Player.ConquerPoints, MsgUpdate.DataType.ConquerPoints);
                                    client.Player.SendUpdate(stream, client.Player.BoundConquerPoints, MsgUpdate.DataType.BoundConquerPoints);
                                    MsgSchedules.SendSysMesage("Congratulations, " + client.Player.Name + " has claim his reward from GuildPoleRank[Member] [ 1K Cps +200k Gold + 2 EP +50 Coins]", MsgMessage.ChatMode.Center);
                                    Game.MsgTournaments.MsgGuildPole2.RoundOwner = null;
                                }
                                else
                                    data.AddText("There is no any rewards now..").AddOption("Alright.").FinalizeDialog();
                            }
                        }
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.OutBanned)]
        public static void OutBanned(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("~If You Want Out Must Pay 1000 Cps.")
                        .AddOption("Ok!.", 1)
                   .AddOption("#Thnx .", 255).AddAvatar(37).FinalizeDialog();

                        break;
                    }
                case 1:
                    {
                        data.AddText("Are You Will Pay 1000 Cps.")
                            .AddOption("Ok,~I~will~pay.", 4)
                       .AddOption("I~would~rather~stay~here.", 255).AddAvatar(37).FinalizeDialog();

                        break;
                    }
                case 4:
                    {
                        if (client.Player.ConquerPoints >= 1000)
                        {
                            if (DeathWish.Protection.SystemBanned.IsBanned(client, false))
                            {
                                Program.SendGlobalPackets.Enqueue(new Game.MsgServer.MsgMessage("This " + client.Player.Name + " Out Map Banneds Hax With 1000 ConquerPoints .", MsgServer.MsgMessage.MsgColor.white, MsgServer.MsgMessage.ChatMode.Center).GetArray(stream));
                                client.Player.ConquerPoints -= 1000;
                                DeathWish.Protection.SystemBanned.RemoveBan(client);

                                client.Socket.Disconnect();
                            }
                            else
                            {
                                client.Teleport(428, 378, 1002);
                                client.Socket.Disconnect();
                            }
                        }
                        else
                        {
                            data.AddText("sorry you not have 1000 conquerpoints .");
                            data.AddOption("Oh.");
                            data.AddAvatar(113);
                            data.FinalizeDialog();
                        }
                        break;
                    }
            }
        }

