        [NpcAttribute(NpcID.OneStarGerment)]
        public static void OneStarGerment(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        if (!client.Inventory.HaveSpace(1))
                        {
                            data.AddText("Please make 1 more space in your inventory.")
                      .AddOption("Let me check.", 255).AddAvatar(7)
                      .FinalizeDialog();
                            break;
                        }
                        data.AddText("Hello Man Select The Garment 1 For 100K You Need " + Program.ServerConfig.ServerName + " Enjoy .");
                        byte page = (byte)(Option + 1);
                        int tocount = (int)Math.Min(Database.CoatStorage.OneStarGerment.Count, (page * 10));
                        for (int x = page - 1; x < tocount; x++)
                        {
                            var garment = Database.CoatStorage.OneStarGerment[x];
                            Database.ItemType.DBItem DBInfo;
                            if (Database.ItemType.Garments.TryGetValue(garment.ID, out DBInfo))
                            {
                                data.AddOption("" + DBInfo.Name + "(" + garment.Stars + "Stars)", (byte)(100 + x));
                            }

                        }
                        data.AddOption("Next Page", page)
                    .AddAvatar(7)
                    .FinalizeDialog();
                        break;
                    }
                default:
                    {
                        if (Option < 100)
                        {
                            data.AddText("Hello Man Select The Garment 1 For 100K You Need " + Program.ServerConfig.ServerName + " Enjoy .");
                            byte page = (byte)(Option + 1);
                            int tocount = (int)Math.Min(Database.CoatStorage.OneStarGerment.Count, (page * 10));
                            for (int x = (page - 1) * 10; x < tocount; x++)
                            {
                                var garment = Database.CoatStorage.OneStarGerment[x];
                                Database.ItemType.DBItem DBInfo;
                                if (Database.ItemType.Garments.TryGetValue(garment.ID, out DBInfo))
                                {
                                    data.AddOption("" + DBInfo.Name + "(" + garment.Stars + "Stars)", (byte)(100 + x));
                                }

                            }
                            if (tocount % 10 == 0)
                                data.AddOption("Next Page", page);
                            data.AddAvatar(7)
                            .FinalizeDialog();
                        }
                        else //get garment.
                        {
                            client.Player.BuyItemS = Database.CoatStorage.OneStarGerment[Option - 100].ID;
                            Database.ItemType.DBItem DBInfo;
                            if (Database.ItemType.Garments.TryGetValue(client.Player.BuyItemS, out DBInfo))
                            {
                                data.AddText("Are you sure you wanna buy this garment (" + DBInfo.Name + ")?!")
                          .AddOption("Sure.", 250)
                          .AddOption("Show me the garment.", 251)
                          .AddOption("Let me check.", 255).AddAvatar(7)
                          .FinalizeDialog();
                            }
                        }

                        break;
                    }
                case 250:
                    {
                        if (!client.Inventory.HaveSpace(1))
                        {
                            data.AddText("Please make 1 more space in your inventory.")
                      .AddOption("Let me check.", 255).AddAvatar(7)
                      .FinalizeDialog();
                            break;
                        }
                        if (client.Player.ConquerPoints < 100000)
                        {
                            data.AddText("Sorry But You Don't Have 100,000 Cps ");
                            data.AddOption("I'll think about it!", 255);
                            data.FinalizeDialog();
                            return;
                        }
                        if (client.Player.BuyItemS != 0)
                        {
                            client.Inventory.Remove(3100055, 1, stream);
                            client.Player.ConquerPoints -= 100000;
                            client.Inventory.Add(stream, client.Player.BuyItemS, 1, 0, 1);
                            Database.ItemType.DBItem DBInfo;
                            if (Database.ItemType.Garments.TryGetValue(client.Player.BuyItemS, out DBInfo))
                                client.CreateBoxDialog("You received 1 " + DBInfo.Name + "");
                            client.Player.BuyItemS = 0;
                        }
                        break;
                    }
                case 251:
                    {

                        Database.ItemType.DBItem DBInfo;
                        if (Database.ItemType.Garments.TryGetValue(client.Player.BuyItemS, out DBInfo))
                        {
                            ShowChatItems.ShowFakeItem(client, stream, client.Player.BuyItemS, DBInfo.Durability);

                            data.AddText("Are you sure you wanna buy this garment (" + DBInfo.Name + ")?!")
                                .AddOption("Sure.", 250)
                                .AddOption("Show me the garment.", 251)
                                .AddOption("Let me check.", 255).AddAvatar(7)
                                .FinalizeDialog();
                        }
                        break;
                    }
            }
        }
