        [NpcAttribute(NpcID.ChangeCharacter)]
        public static void ChangeCharacter(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("I devote all my life to the research of eternity. And finally I know the secret of rebirth! Well, anything I can help you with?");
                        if (client.Player.Reborn == 0)
                        {
                            data.AddOption("Change~This~class.", 1);
                        }
                        if (client.Player.Reborn == 1)
                        {
                            data.AddOption("Change~This~class.", 1);
                            data.AddOption("Change~First~Class.", 2);
                        }
                        if (client.Player.Reborn == 2)
                        {
                            data.AddOption("Change~This~class.", 1);
                            data.AddOption("Change~First~Class.", 2);
                            data.AddOption("Change~Secounde~Class.", 3);
                        }
                        data.AddOption("Just~passing~by.", 255);
                        data.AddAvatar(67).FinalizeDialog();
                        break;
