        [NpcAttribute(NpcID.ChiMaker)]
        public static void ChiMaker(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        client.SelectedStage = 0;
                        client.SelectedAttribute = 0;
                        if (client.Player.MyChi != null)
                        {
                            bool have = false;
                            int count = 0;
                            foreach (var obj in client.Player.MyChi)
                            {
                                if (obj.UnLocked)
                                {
                                    have = true;
                                    dialog.Option(obj.Type.ToString(), (byte)(1 + count));
                                    count++;
                                }
                            }
                            if (have)
                            {
                                //dialog.Text("You don't have enough 1 CPs.").AddAvatar(63).FinalizeDialog();

                                dialog.Text("Hello, I`m Chi Seller On each attribute, I'll take 10K Cps for each Attribute.").AddAvatar(261).FinalizeDialog();
                            }
                            else
                            {
                                dialog.Text("Sorry But You Don't Have chi Yet.").Option("I'll think about it!", 255).AddAvatar(261).FinalizeDialog();
                            }
                        }
                        else
                        {
                            dialog.Text("Sorry But You Don't Have chi Yet.").Option("I'll think about it!", 255).AddAvatar(261).FinalizeDialog();
                        }
                        break;
                    }
                default:
                    {
                        if (!client.Inventory.Contain(3005544, 1))
                        {
                            dialog.Text("You don't have Chi Token .").AddAvatar(261).FinalizeDialog();
                            break;
                        }
                        else
                        {
                            int mStage = Option;
                            if (mStage >= 1 && mStage <= 4)
                            {
                                if (!client.Inventory.Contain(3005544, 1))
                                {
                                    dialog.Text("You don't have Chi Token .").AddAvatar(261).FinalizeDialog();

                                    //dialog.Text("You don't have enough donation points,I just want 2 donation points.").AddAvatar(63).FinalizeDialog();
                                    break;
                                }
                                client.SelectedStage = mStage;
                                dialog.Text("You Choose " + ((MsgChiInfo.ChiPowerType)mStage).ToString() + " stage. please select Attribute you want to change ");
                                for (int i = 0; i < 4; i++)
                                {
                                    dialog.Option("Attribute [" + (byte)(i + 1) + "]", (byte)(i + 1 + 4));
                                }
                                dialog.Option("I'll think about it!", 255);
                                dialog.AddAvatar(261).FinalizeDialog();
                                break;
                            }
                            else if (mStage >= 4 && mStage <= 8)
                            {
                                if (!client.Inventory.Contain(3005544, 1))
                                {
                                    dialog.Text("You don't have Chi Token .").AddAvatar(261).FinalizeDialog();
                                    break;
                                }
                                client.SelectedAttribute = mStage - 4;
                                var PowerType = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), ((MsgChiInfo.ChiPowerType)client.SelectedStage).ToString());
                                var Power = client.Player.MyChi.Where(p => p.Type == PowerType).FirstOrDefault();
                                dialog.Text("You Choose Attribute [" + client.SelectedAttribute + "] please select AttributeType you want to change ");
                                for (int i = 0; i < Program.AtributesType.Length; i++)
                                {
                                    var type = Program.AtributesType[i];
                                    if (Power.Fields[0].Item1.ToString() != type && Power.Fields[1].Item1.ToString() != type && Power.Fields[2].Item1.ToString() != type && Power.Fields[3].Item1.ToString() != type)
                                    {
                                        dialog.Option(type, ((byte)(((i + 1) * 10))));
                                    }
                                }
                                dialog.Option("Back", (byte)client.SelectedStage);
                                dialog.Option("I'll think about it!", 255);
                                dialog.AddAvatar(261).FinalizeDialog();
                                break;
                            }
                            else
                            {
                                if (!client.Inventory.Contain(3005544, 1))
                                {
                                    dialog.Text("You don't have Chi Token .").AddAvatar(261).FinalizeDialog();

                                    break;
                                }
                                var typex = mStage / 10;
                                var Mode = client.SelectedStage;
                                var pos = client.SelectedAttribute - 1;
                                var PowerType = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), ((MsgChiInfo.ChiPowerType)Mode).ToString());
                                var Power = client.Player.MyChi.Where(p => p.Type == PowerType).FirstOrDefault();
                                var attributes = Power.Fields;
                                foreach (var attr in attributes)
                                {
                                    if (attr == null) continue;
                                    if (attr.Item1 == (Role.Instance.Chi.ChiAttributeType)typex)
                                    {
                                        client.Player.MessageBox("Sorry you can't muliplay stats", null, null);
                                        return;
                                    }
                                }
                                var attribte = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), ((Role.Instance.Chi.ChiAttributeType)typex).ToString());
                                var Value = Role.Instance.Chi.MaxPower(attribte);
                                attributes[pos] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                                client.Inventory.Remove(3005544, 1, stream);
                                client.Teleport(428, 378, 1002);
                                Role.Instance.Chi.ComputeStatus(client.Player.MyChi);
                                client.Equipment.QueryEquipment(client.Equipment.Alternante, false);
                                Game.MsgServer.MsgChiInfo.MsgHandleChi.SendInfo(client, Game.MsgServer.MsgChiInfo.Action.Send);
                            }
                        }
                        break;
                    }
            }
        }
