        [NpcAttribute(NpcID.GoldAndCPS)]
        public static void GoldAndCPS(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {

                        data.AddText("Hey " + client.Player.Name + "Im Glad 2 See U ")
                            //   .AddOption("Exchange~a~DBScroll~for~[10kChi Points].", 1)
                            //    .AddOption("Exchange~a~DragonBall~for[20Cps].", 2)
                       .AddOption("Exchange Gold For Cps And reverse.", 3)
                       .AddOption("I~have~nothing.", 255).AddAvatar(7).FinalizeDialog();


                        break;
                    }
                case 1:
                    {
                        if (client.Inventory.Contain(Database.ItemType.DragonBallScroll, 1))
                        {
                            client.Inventory.Remove(Database.ItemType.DragonBallScroll, 1, stream);
                            client.Inventory.Add(stream, 3000740);

                            client.CreateBoxDialog("Congratulations!You~have~got~10k~ChiPack~in~your~inventory");
                        }
                        else
                        {
                            data.AddText("A7a~Where~is~your~DBScroll?")
                          .AddOption("Er,~sorry.~I'm not have DBScroll.", 255).AddAvatar(7).FinalizeDialog();
                        }

                        break;
                    }
                case 2:
                    {
                        if (client.Inventory.Contain(Database.ItemType.DragonBall, 1))
                        {
                            client.Inventory.Remove(Database.ItemType.DragonBall, 1, stream);
                            client.Player.ConquerPoints += 20;

                            client.CreateBoxDialog("Congratulations!You~have~got~20~CPs~in~your~inventory");
                        }
                        else
                        {
                            data.AddText("A7a~Where~is~your~DragonBall?")
                          .AddOption("Er,~sorry.~I'm not have Dragon Ball.", 255).AddAvatar(7).FinalizeDialog();
                        }

                        break;
                    }
                case 3:
                    {
                        data.AddText("Welcome Mr" + client.Player.Name + "At [HORUS's ExchangeSHop]! ")
              .AddOption("Change 5k[cps] for 10m[Gold]", 4)
              .AddOption("Change 10m gold for 3k Cps", 5)
              .AddOption("No Thanks", 255).AddAvatar(7).FinalizeDialog();

                        break;
                    }
                case 4:
                    {
                        if (client.Player.ConquerPoints >= 5000)
                        {
                            client.Player.ConquerPoints -= 5000;
                            client.Player.Money += 10000000;
                            client.Player.SendUpdate(stream, client.Player.Money, MsgServer.MsgUpdate.DataType.Money);

                            client.CreateBoxDialog("Congratulations!You~have~got~10M~Gold~in~your~inventory");
                        }
                        else
                        {
                            data.AddText("You do not have 5k cps with you.")
                             .AddOption("I~see", 255).AddAvatar(7).FinalizeDialog();
                        }

                        break;
                    }
                case 5:
                    {
                        if (client.Player.Money >= 10000000)
                        {
                            client.Player.Money -= 10000000;
                            client.Player.ConquerPoints += 3000;
                            client.Player.SendUpdate(stream, client.Player.Money, MsgServer.MsgUpdate.DataType.Money);

                            client.CreateBoxDialog("Congratulations!You~have~got~3k~CPs~in~your~inventory");
                        }
                        else
                        {
                            data.AddText("You do not have 20m gold with you.")
                             .AddOption("I~see", 255).AddAvatar(7).FinalizeDialog();
                        }

                        break;
                    }



            }
        }










