        [NpcAttribute(NpcID.DonationSelector)]
        public static void DontaionTime(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hello [ " + client.Player.Name + " ] Which One Would You Like To Select As Period Rank .");
                        data.AddOption("King.", 12)
                            .AddOption("Prince .", 9)
                            .AddOption("Duke .", 7)
                            .AddOption("Earl .", 5)
                            .AddOption("Baroon .", 3)
                            .AddOption("Knight .", 1)
                            .AddOption("Check Time .", 15)
                        .AddOption("#Thnx .", 255)
                        .AddAvatar(6).FinalizeDialog();
                        break;
                    }
                case 1:
                case 3:
                case 5:
                case 7:
                case 9:
                case 12:
                    {
                        client.Player.selectedrank = Option;
                        data.AddText("Hello [ " + client.Player.Name + " ] How Much Hours Would You Select To Period.");
                        data.AddInput("Day :", 15)
                        .AddOption("#Thnx  .", 255)
                        .AddAvatar(6).FinalizeDialog();
                        break;
                    }
                case 15:
                    {
                        int Hours = 0;
                        if (int.TryParse(Input, out Hours))
                        {
                            client.Player.PeriodRank(client.Player.selectedrank, 0, Hours);
                            client.SendSysMesage(string.Format("Period Rank Mode Activated Ends on {0}.", client.Player.Nobility.PaidPeriod.ToShortTimeString()));
                        }
                        client.SendSysMesage("Invalid Input Hours.");
                        break;
                    }
            }
        }
