        [NpcAttribute(NpcID.clearinventory)]
        public static void clearinventory(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    {
                        data.AddText("I clear Your Item")
                                        .AddOption("Clearinventory", 5)
                           .AddOption("No.", 255).AddAvatar(0).FinalizeDialog();
                        break;
                    }

                case 5:
                    {
                        using (var rec = new ServerSockets.RecycledPacket())
                            client.Inventory.Clear(rec.GetStream());
                        break;
                    }


            }
        }
        [Npc(NpcID.ShopMarket)]
        public static void ShopMarket(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    dialog.AddText("Hello , Shops In My Server .").AddOption("Level 140 Free", 9).AddOption("#Thnx .", 255).AddAvatar(200).FinalizeDialog(false);
                    break;
                case 9:
                    if (client.Player.ConquerPoints < 50000)
                    {
                        client.Player.ConquerPoints -= 50000;
                        client.UpdateLevel(stream, 140, false, true);
                        dialog.AddText("Okay, you have a Level 140! ").AddOption("Thx ", 0xff).AddAvatar(15).FinalizeDialog(false);
                        break;
                    }
                    else
                    {
                        dialog.AddText("Sorry But You Don't Have 50,000 Cps ");
                        dialog.AddOption("I'll think about it!", 255);
                        dialog.FinalizeDialog();
                    }
                    break;
            }
        }
        [Npc(NpcID.ShopMarkets)]
        public static void ShopMarkets(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    dialog.AddText("Hello , Shop vip In My Server .").AddOption("VIP 6 : 2 Hour Ticket For 2m Cps", 3).AddOption("VIP 6 : 12 Hour For 9m Cps", 5).AddOption("#Thnx .", 255).AddAvatar(200).FinalizeDialog(false);
                    break;

                case 3:
                    if (client.Player.ConquerPoints >= 2000000)
                    {
                        client.Player.ConquerPoints -= 2000000;
                        client.Inventory.Add100(780010, 0, 1, stream);
                        dialog.AddText("You Have Bought Vip4 token for 2m cps.").AddOption("Thanks!", 0xff).AddAvatar(0xa6).FinalizeDialog(false);
                        break;
                    }
