        [Npc(NpcID.ReallotPoints)]
        public static void ReallotPoints(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            ushort num;
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    dialog.AddText("Hello friend. I can help you set your Atributes points fast .. its hard work for you.").AddOption("Vitality Points.", 5).AddOption("Agility Points.", 6).AddOption("Strength Points.", 7).AddOption("Spirit Points.", 8).AddOption("Just~passing~by.", 0xff).AddAvatar(6).FinalizeDialog(false);
                    break;

                case 1:
                    if (ushort.TryParse(Input, out num))
                    {
                        if (client.Player.Atributes < num)
                        {
                            client.CreateBoxDialog("You dont have: " + Input + " Atribute points.");
                            break;
                        }
                        client.Player.Vitality = (ushort)(client.Player.Vitality + num);
                        client.Player.Atributes = (ushort)(client.Player.Atributes - num);
                        client.Player.SendUpdate(stream, (long)client.Player.Vitality, MsgUpdate.DataType.Atributes | MsgUpdate.DataType.Money, false);
                        client.Player.SendUpdate(stream, (long)client.Player.Atributes, MsgUpdate.DataType.Atributes, false);
                        client.Equipment.QueryEquipment(client.Equipment.Alternante, false);
                    }
                    break;

                case 2:
                    if (ushort.TryParse(Input, out num))
                    {
                        if (client.Player.Atributes < num)
                        {
                            client.CreateBoxDialog("You dont have: " + Input + " Atribute points.");
                            break;
                        }
                        client.Player.Agility = (ushort)(client.Player.Agility + num);
                        client.Player.Atributes = (ushort)(client.Player.Atributes - num);
                        client.Player.SendUpdate(stream, (long)client.Player.Agility, MsgUpdate.DataType.Agility, false);
                        client.Player.SendUpdate(stream, (long)client.Player.Atributes, MsgUpdate.DataType.Atributes, false);
                        client.Equipment.QueryEquipment(client.Equipment.Alternante, false);
                        if (client.Player.Agility > 300 && !Database.AtributesStatus.IsWarrior(client.Player.Class) && !Database.AtributesStatus.IsTrojan(client.Player.Class))
                        {

                            ushort restofagility = client.Player.Agility;
                            num = (ushort)(client.Player.Agility - 300);
                            client.Player.Agility = 300;

                            client.Player.Atributes += num;
                            client.Player.SendUpdate(stream, client.Player.Agility, Game.MsgServer.MsgUpdate.DataType.Agility);
                            client.Player.SendUpdate(stream, client.Player.Atributes, Game.MsgServer.MsgUpdate.DataType.Atributes);
                            client.CreateBoxDialog("You have Reach the Highset Points to Agility [Max is 300] " + num + " Points Add to Attribute Points");
                        }
                        if (client.Player.Agility > 150 && (Database.AtributesStatus.IsWarrior(client.Player.Class) || Database.AtributesStatus.IsTrojan(client.Player.Class)))
                        {

                            ushort restofagility = client.Player.Agility;
                            num = (ushort)(client.Player.Agility - 150);
                            client.Player.Agility = 150;

                            client.Player.Atributes += num;
                            client.Player.SendUpdate(stream, client.Player.Agility, Game.MsgServer.MsgUpdate.DataType.Agility);
                            client.Player.SendUpdate(stream, client.Player.Atributes, Game.MsgServer.MsgUpdate.DataType.Atributes);
                            client.CreateBoxDialog("You have Reach the Highset Points to Agility Of Warrior or Trojan [Max is 150] " + num + " Points Add to Attribute Points");
                        }
                    }
                    break;

                case 3:
                    if (ushort.TryParse(Input, out num))
                    {
                        if (client.Player.Atributes < num)
                        {
                            client.CreateBoxDialog("You dont have: " + Input + " Atribute points.");
                            break;
                        }
                        client.Player.Strength = (ushort)(client.Player.Strength + num);
                        client.Player.Atributes = (ushort)(client.Player.Atributes - num);
                        client.Player.SendUpdate(stream, (long)client.Player.Strength, MsgUpdate.DataType.Atributes | MsgUpdate.DataType.Experience, false);
                        client.Player.SendUpdate(stream, (long)client.Player.Atributes, MsgUpdate.DataType.Atributes, false);
                        client.Equipment.QueryEquipment(client.Equipment.Alternante, false);
                    }
                    break;

                case 4:
                    if (ushort.TryParse(Input, out num))
                    {
                        if (client.Player.Atributes < num)
                        {
                            client.CreateBoxDialog("You dont have: " + Input + " Atribute points.");
                            break;
                        }
                        client.Player.Spirit = (ushort)(client.Player.Spirit + num);
                        client.Player.Atributes = (ushort)(client.Player.Atributes - num);
                        client.Player.SendUpdate(stream, (long)client.Player.Spirit, MsgUpdate.DataType.Experience | MsgUpdate.DataType.Stamina, false);
                        client.Player.SendUpdate(stream, (long)client.Player.Atributes, MsgUpdate.DataType.Atributes, false);
                        client.Equipment.QueryEquipment(client.Equipment.Alternante, false);
                    }
                    break;

                case 5:
                    dialog.AddText("Enter the Vitality points.").AddInput("Vitality Points.", 1).AddOption("Just~passing~by.", 0xff).AddAvatar(6).FinalizeDialog(false);
                    break;

                case 6:
                    dialog.AddText("Enter the Agility points.").AddInput("Agility Points.", 2).AddOption("Just~passing~by.", 0xff).AddAvatar(6).FinalizeDialog(false);
                    break;

                case 7:
                    dialog.AddText("Enter the Strength points.").AddInput("Strength Points.", 3).AddOption("Just~passing~by.", 0xff).AddAvatar(6).FinalizeDialog(false);
                    break;

                case 8:
                    dialog.AddText("Enter the Spirit points.").AddInput("Spirit Points.", 4).AddOption("Just~passing~by.", 0xff).AddAvatar(6).FinalizeDialog(false);
                    break;
            }
        }
        
