        [NpcAttribute(NpcID.Veterans)]
        public static void Veterans(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hey " + client.Player.Name + " i am The Smaill Quests Manager How Can i Help You What Quest You Want to join?!");
                        data.AddText("Let Me Tell You Welcome To [ " + Program.ServerConfig.ServerName + " Conquer ] Enjoy .");
                        data.AddOption("VeteransWar[Join] .", 50);
                        data.AddOption("VeteransWar[Claim] .", 51);
                        data.AddOption("#Thanks .", 255).AddAvatar(80).FinalizeDialog();
                        break;
                    }
                case 170:
                    {

                        data.AddText("Veterans [ Even:40 ] End [ Even:45 ] .\n");
                        data.AddOption("#Thanks .", 255).AddAvatar(80).FinalizeDialog();
                        break;
                    }

                case 50:
                    {
                        if (Game.MsgTournaments.MsgVeteransWar.Proces == ProcesType.Alive)
                        {
                            client.Teleport(95, 110, 6526);
                        }
                        else
                            client.SendSysMesage("Veterans War has ben finished .. Please come back later at Even:40 To Even:45");
                        break;
                    }
                case 51:
                    {
                        if (Game.MsgTournaments.MsgVeteransWar.Proces == ProcesType.Dead)
                        {
                            if (Game.MsgTournaments.MsgVeteransWar.RoundOwner != null)
                            {
                                if (Game.MsgTournaments.MsgVeteransWar.RoundOwner.GuildID == client.Player.UID)
                                {

                                    client.Player.ConquerPoints += 4300;
                                    client.Inventory.Add(stream, 3009003, 1);
                                    client.Player.PIKAPoint += 1;
                                    MsgSchedules.SendSysMesage("Congratulations, " + client.Player.Name + " has claim his reward from Veterans War .. 5k CPs + Stone+3 + 1 Event Points.", MsgMessage.ChatMode.Center);
                                    Game.MsgTournaments.MsgVeteransWar.RoundOwner = null;
                                }
                            }
                        }
                        break;

                    }
            }

        }

