        [NpcAttribute(NpcID.Portal5)]
        public static void Portal5(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    {
                        data.AddText("This portal will send you to the TwinCity station. Do you want to use the portal now?")
                            .AddOption("Yes.", 1)
                           .AddOption("No.", 255).AddAvatar(0).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.Player.HitPoints < 1)
                            return;
                        client.Teleport(430, 391, 1002);
                        client.Player.SetPkMode(DeathWish.Role.Flags.PKMode.Capture);
                        break;
                    }
                default:
                    break;
            }
        }
