        [NpcAttribute(NpcID.NewEliteGuildWar)]
        public static void NewEliteGuildWar(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            dialog.AddAvatar(36);
            switch (Option)
            {
                case 0:
                    {
                        dialog.AddText("Hi " + client.Player.Name + ", I'm the EliteGuildWar manager ..The War Start Every Day At 19:00 There are 3 Poles Every one Take 20 Minutes ?");
                            dialog.AddOption("Can Join!", 1);
                            dialog.AddOption("Claim Prize", 2);
                        dialog.AddOption("Thanks.", 255);
                        dialog.FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (Game.MsgTournaments.MsgSchedules.EliteGuildWar1st.Proces == MsgTournaments.ProcesType.Alive || Game.MsgTournaments.MsgSchedules.EliteGuildWar2nd.Proces == MsgTournaments.ProcesType.Alive || Game.MsgTournaments.MsgSchedules.EliteGuildWar3rd.Proces == MsgTournaments.ProcesType.Alive)
                        {
                            byte RandTele = (byte)Program.GetRandom.Next(1, 14);
                            switch (RandTele)
                            {
                                case 1: client.Teleport(47, 132, 6625); break;
                                case 2: client.Teleport(39, 152, 6625); break;
                                case 3: client.Teleport(87, 111, 6625); break;
                                case 4: client.Teleport(92, 86, 6625); break;
                                case 5: client.Teleport(95, 146, 6625); break;
                                case 6: client.Teleport(87, 173, 6625); break;
                                case 7: client.Teleport(64, 182, 6625); break;
                                case 8: client.Teleport(110, 172, 6625); break;
                                case 9: client.Teleport(142, 165, 6625); break;
                                case 10: client.Teleport(177, 172, 6625); break;
                                case 11: client.Teleport(196, 118, 6625); break;
                                case 12: client.Teleport(133, 76, 6625); break;
                                default: client.Teleport(91, 61, 6625); break;
                            }
                        }
                        else
                        {
                            dialog.AddText("The EliteGuildWar is not started yet EveryDay In [ 19:00 ].").AddOption("Alright.").FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        dialog.AddText("Hi " + client.Player.Name + ", Which Prize You Want To Claim It ?");
                        dialog.AddOption("1st-Pole Prize", 3);
                        dialog.AddOption("2nd-Pole Prize", 4);
                        dialog.AddOption("3rd-Pole Prize", 5);
                        dialog.AddOption("Champion Of 3 Poles Prize", 6);
                        dialog.AddOption("Thanks.", 255);
                        dialog.FinalizeDialog();
                        break;
                    }
                case 3:
                    {

                        if (Game.MsgTournaments.MsgSchedules.EliteGuildWar1st.Proces != MsgTournaments.ProcesType.Alive)
                        {
                            if (Game.MsgTournaments.MsgSchedules.EliteGuildWar1st.RoundOwner != null && Role.Instance.Guild.GuildPoll.ContainsKey(Game.MsgTournaments.MsgSchedules.EliteGuildWar1st.RoundOwner.GuildID))
                            {
                                if (client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader)
                                {
                                    if (client.Player.MyGuild.Info.GuildID == Game.MsgTournaments.MsgSchedules.EliteGuildWar1st.RoundOwner.GuildID)
                                    {

                                        client.Player.ConquerPoints += 10750;
                                        client.Player.BoundConquerPoints += 50;
                                        client.Player.EGWIN += 1;
                                        Game.MsgTournaments.MsgSchedules.EliteGuildWar1st.RoundOwner = null;
                                        Game.MsgTournaments.MsgSchedules.SendSysMesage(client.Player.Name + " has receved 10750 CPs + 50 Coins  for winning EliteGuildWar 1st Pole.", MsgMessage.ChatMode.Center);
                                    }
                                    else
                                        dialog.AddText("You dont have any rewrd to claim.").AddOption("Alright.").FinalizeDialog();
                                }
                                else
                                    dialog.AddText("Only the guild leader can claim the reward.").AddOption("Alright.").FinalizeDialog();
                            }
                            else
                                dialog.AddText("There is no any rewards now..").AddOption("Alright.").FinalizeDialog();
                        }
                        else
                            dialog.AddText("Please come back when eliteguildwar is finished.").AddOption("Alright.").FinalizeDialog();
                        break;
                    }
                case 4:
                    {

                        if (Game.MsgTournaments.MsgSchedules.EliteGuildWar2nd.Proces != MsgTournaments.ProcesType.Alive)
                        {
                            if (Game.MsgTournaments.MsgSchedules.EliteGuildWar2nd.RoundOwner != null && Role.Instance.Guild.GuildPoll.ContainsKey(Game.MsgTournaments.MsgSchedules.EliteGuildWar2nd.RoundOwner.GuildID))
