                            client.SendSysMesage(string.Format("Paid Rank : {0} Time Left : {1} ", client.Player.Nobility.PaidRank.ToString(), (span.Days > 0 ? span.Days + " days, " : string.Empty) + (span.Hours > 0 ? span.Hours + " hours, " : string.Empty) + (span.Minutes > 0 ? span.Minutes + " minutes, " : string.Empty) + (span.Seconds > 0 ? span.Seconds + " seconds" : string.Empty) + "."));
                        }
                        break;
                    }
            }
        }
