        [Npc(NpcID.MARSHALstuff)]
        public static void MARSHALStuff(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    dialog.AddText("Select What's Equipment u want?").AddOption("Headgear", 1).AddOption("Armor", 2).AddOption("Necklace", 3).AddOption("Weapons", 4).AddOption("Ring", 5).AddOption("Boots", 6).AddOption("Talisman", 7).AddOption("#Tnx", 255).FinalizeDialog(false);
