                                            var com = new MySqlCommand(MySqlCommandType.INSERT);
                                            com.Insert("accounts").Insert("Username", client.Player.NewUser).Insert("Password", pass);
                                            if (com.Execute2() > 0)
                                            {
                                                client.Player.MessageBox("Account successfully Created", null, null);
                                            }
                                            else
                                            {
                                                client.Player.MessageBox("Something went wrong", null, null);
