                            client.Player.MessageBox("Something went wrong", null, null);
                        }
                        break;
                    }
                case 32:
                    {
                        try
                        {
                            string newpass = Input;
                            var com = new MySqlCommand(MySqlCommandType.UPDATE);
                            com.Update("accounts").Set("Password", newpass)
                                .Where("EntityID", client.Player.UID);
                            if (com.Execute2() > 0)
                            {
                                client.Player.MessageBox("Account password successfully changed your new password is " + newpass, null, null);
                            }
