        [NpcAttribute(NpcID.WarOfPlayers)]
        public static void WarOfPlayers(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hey " + client.Player.Name + " Here War-of-Player Quest You Want to join?!");
                        if (Game.MsgTournaments.MsgWarOfPlayers.Proces == MsgTournaments.ProcesType.Alive)
                            data.AddOption("WarOfPlayers[Open] .", 40);
                        else
                            data.AddOption("WarOfPlayers[End] .", 170);
                        data.AddOption("WarOfPlayers[Claim] .", 41);
                        data.AddOption("[---Sound---]", 2)
                 .AddOption("Thanks.", 255).FinalizeDialog();
                        break;
                    }
                case 170:
                    {


                        data.AddText("War-Of-Players Start [ xx:45 ] & End [ xx:55 ] .\n");
                        data.AddOption("#Thanks .", 255);
                        //.AddText("Enjoy .");
                        data.FinalizeDialog();
                        return;
                    }
                case 2:
                    {
                        client.Player.SendString(stream, MsgServer.MsgStringPacket.StringID.Sound, 0, false, "sound/DIABLO.wav", "1");
                        break;
                    }
                case 40:
                    {
                        if (Game.MsgTournaments.MsgWarOfPlayers.Proces == ProcesType.Alive)
                        {
                            client.Teleport(145, 150, 9);
                        }
                        else
                            client.SendSysMesage("WarOfPlayers War has ben finished .. Please come back later at xx.20 To xx:30.");
                        break;
                    }
                case 41:
                    {
                        if (Game.MsgTournaments.MsgWarOfPlayers.Proces == ProcesType.Dead)
                        {
                            if (Game.MsgTournaments.MsgWarOfPlayers.RoundOwner != null)
                            {
                                if (Game.MsgTournaments.MsgWarOfPlayers.RoundOwner.ClanID == client.Player.UID)
                                {

                                    client.Player.ConquerPoints += 5000;
                                    client.Player.Money += 1000000;
                                    MsgSchedules.SendSysMesage("Congratulations, " + client.Player.Name + " has claim his reward from WarOfPlayers .. 5.000 CPs and -- 1.000.000 Gold .", MsgMessage.ChatMode.Center);
                                    Game.MsgTournaments.MsgWarOfPlayers.RoundOwner = null;
                                }
                            }
                        }
                        break;

                    }
            }

        }
