        [NpcAttribute(NpcID.Polewar1)]
        public static void Polewar1(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {

                        data.AddText("Hey " + client.Player.Name + " Here The Pole Quests Manager How Can i Help You?!\n");
                        data.AddText("Player-Pole Start [<tip color=0xff00fa00> " + " xx:45 To xx:50 " + " </tip> ]\n");
                        data.AddText("Guild-Pole Start [<tip color=0xff00fa00> " + " xx:55 To xx:00  " + " </tip> ]\n");
                        if (Game.MsgTournaments.MsgEmperorWar.Proces == ProcesType.Alive)
                            data.AddOption("Player-Pole [Open]", 1);
                        else
                            data.AddOption("Player-Pole [Prize]", 2);

                        if (Game.MsgTournaments.MsgVeteransWar.Proces == ProcesType.Alive)
                            data.AddOption("Guild-Pole [Open]", 3);
                        else
                            data.AddOption("Guild-Pole [Prize].", 4);
                        data.AddOption("#Thanks .", 255).AddAvatar(4).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (Game.MsgTournaments.MsgEmperorWar.Proces == ProcesType.Alive)
                        {
                            client.Teleport(156, 185, 5979);
                            client.Player.SetPkMode(DeathWish.Role.Flags.PKMode.PK);
                        }
                        else
                            client.SendSysMesage("Player-Pole  has ben finished.");
                        break;
                    }
                case 2:
                    {
                        if (Game.MsgTournaments.MsgEmperorWar.Proces == ProcesType.Dead)
                        {
                            if (Game.MsgTournaments.MsgEmperorWar.RoundOwner != null)
                            {
                                if (Game.MsgTournaments.MsgEmperorWar.RoundOwner.UID == client.Player.UID)
                                {
                                    if (client.Inventory.HaveSpace(1))
                                    {

                                        client.Player.ConquerPoints += 7000;
                                        client.Inventory.AddItemWitchStack(730003, 0, 1, stream);
                                        client.Player.PIKAPoint += 1;
                                        client.Player.BoundConquerPoints += 10;
                                        client.Player.SendUpdate(stream, client.Player.ConquerPoints, MsgUpdate.DataType.ConquerPoints);
                                        client.Player.SendUpdate(stream, client.Player.BoundConquerPoints, MsgUpdate.DataType.BoundConquerPoints);
                                        MsgSchedules.SendSysMesage("Congratulations, " + client.Player.Name + " has claim his reward from Players-Pole [ 7k Cps & Stone +3 & 10 Coins + 1 EP]  .", MsgMessage.ChatMode.Center);
                                        Game.MsgTournaments.MsgEmperorWar.RoundOwner = null;
                                    }
                                    else
                                    {
                                        data.AddText("Please make 1 more spaces in your inventory.")
                                        .AddOption("Let me check.", 255).AddAvatar(110).FinalizeDialog();
                                        break;
                                    }

                                }
                                else
                                    client.SendSysMesage("Sorry But You Are n`t The Winner.");

                            }
                            else
                                data.AddText("You dont have any rewrd to claim.").AddOption("Alright.").FinalizeDialog();
                        }

                        break;

                    }
                case 3:
                    {
                        if (Game.MsgTournaments.MsgVeteransWar.Proces == ProcesType.Alive)
                        {
                            client.Teleport(156, 185, 6979);
                            client.Player.SetPkMode(DeathWish.Role.Flags.PKMode.Team);
                        }
                        else
                            client.SendSysMesage("Guild-Pole has ben finished.");
                        break;
                    }
                case 4:
                    {
                        if (Game.MsgTournaments.MsgVeteransWar.Proces != MsgTournaments.ProcesType.Alive)
                        {
                            if (Game.MsgTournaments.MsgVeteransWar.RoundOwner != null && Role.Instance.Guild.GuildPoll.ContainsKey(Game.MsgTournaments.MsgVeteransWar.RoundOwner.GuildID))
                            {
                                if (client.Player.GuildRank == Role.Flags.GuildMemberRank.GuildLeader)
                                {
                                    if (client.Player.MyGuild.Info.GuildID == Game.MsgTournaments.MsgVeteransWar.RoundOwner.GuildID)
                                    {
                                        if (client.Inventory.HaveSpace(2))
                                        {
                                            client.Player.ConquerPoints += 5000;
                                            client.Inventory.AddItemWitchStack(730003, 0, 2, stream);
                                            client.Player.PIKAPoint += 1;
                                            client.Player.BoundConquerPoints += 10;
                                            client.Player.SendUpdate(stream, client.Player.ConquerPoints, MsgUpdate.DataType.ConquerPoints);
                                            client.Player.SendUpdate(stream, client.Player.BoundConquerPoints, MsgUpdate.DataType.BoundConquerPoints);
                                            Game.MsgTournaments.MsgVeteransWar.RoundOwner = null;
                                            Game.MsgTournaments.MsgSchedules.SendSysMesage("Congratulations,Leader " + client.Player.Name + " has receved  [ 5k Cps & 2 Stone +3 & 1 EP & 10 Coins]   for winning Guild-Pole.", MsgMessage.ChatMode.Center);
                                        }
                                        else
                                        {
                                            data.AddText("Please make 2 more spaces in your inventory.")
                                            .AddOption("Let me check.", 255).AddAvatar(110).FinalizeDialog();
                                            break;
                                        }
                                    }
                                    else
                                        data.AddText("You dont have any rewrd to claim.").AddOption("Alright.").FinalizeDialog();
                                }
                                else
                                    data.AddText("Only the guild leader can claim the reward.").AddOption("Alright.").FinalizeDialog();
                            }
                            else
                                data.AddText("There is no any rewards now..").AddOption("Alright.").FinalizeDialog();
                        }
                        else
                            data.AddText("Please come back when Guild-Pole is finished.").AddOption("Alright.").FinalizeDialog();
                        break;
                    }
            }

        }
