        [NpcAttribute(NpcID.TopHourly)]
        public static void TopHourly(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hey " + client.Player.Name + " i am The Smaill Quests Manager How Can i Help You What Quest You Want to join?! \n");
                        data.AddText("<tip color=0xfff05050> " + "Every Hour Start" + "</tip>  [<tip color=0xff00fa00> " + " From xx:12 To xx:44 Every 4 Minutes One Start " + " </tip> ]\n");
                        data.AddText("<tip color=0xfff05050> " + "Winner Reward" + "</tip>  [<tip color=0xff00fa00> " + " 30000 Cps & 2 DIABLO Spin & 1 E-P " + " </tip> ]\n");
                        {

                            if (DateTime.Now.Minute >= 12 && DateTime.Now.Minute <= 15)
                                data.AddOption("D-Tops [Join ]", 4);
                            else

                                if (DateTime.Now.Minute >= 16 && DateTime.Now.Minute <= 19)
                                    data.AddOption("D-Tops [Join ]", 5);
                                else

                                    if (DateTime.Now.Minute >= 20 && DateTime.Now.Minute <= 23)
                                        data.AddOption("D-Tops [Join ]", 6);
                                    else

                                        if (DateTime.Now.Minute >= 24 && DateTime.Now.Minute <= 27)
                                            data.AddOption("D-Tops [Join ]", 7);
                                        else

                                            if (DateTime.Now.Minute >= 28 && DateTime.Now.Minute <= 31)
                                                data.AddOption("D-Tops [Join ]", 8);
                                            else

                                                if (DateTime.Now.Minute >= 32 && DateTime.Now.Minute <= 35)
                                                    data.AddOption("D-Tops [Join ]", 9);
                                                else
                                                    if (DateTime.Now.Minute >= 36 && DateTime.Now.Minute <= 39)
                                                        data.AddOption("D-Tops [Join ]", 10);
                                                    else
                                                        if (DateTime.Now.Minute >= 40 && DateTime.Now.Minute <= 43)
