        [NpcAttribute(NpcID.WinnerWeeklyPK)]
        public static void WinnerWeeklyPK(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hey there " + client.Player.Name + " Would you like to Claim Your Prize?.")
                                .AddOption("Yes-Sir", 26)
                                .AddOption("Twin-City", 25)
                        .AddOption("#Thnx .", 255)
                        .AddAvatar(63).FinalizeDialog();
                        break;
                    }
                case 26:
                    {
                        DateTime Now64 = DateTime.Now;
                        int alive = 0;
                        foreach (Client.GameClient Entitys in Database.Server.GamePoll.Values)
                            if (Entitys.Player.Map == 1508 && Entitys.Player.Alive && client.Player.HitPoints >= 1) alive++;
                        if (Now64.Hour == 21 && Now64.Minute >= 6 && Now64.Minute < 20)
                        {
                            if (alive == 1)
                            {
                                client.Player.ConquerPoints += 5000;
                                // client.Player.Money += 100000000;
                                client.Player.PIKAPoint += 10;
                                client.Player.AddFlag(MsgServer.MsgUpdate.Flags.WeeklyPKChampion, Role.StatusFlagsBigVector32.WeeklyFlag, false);
                                MsgSchedules.SendSysMesage(" Congratulations " + client.Player.Name + " claimed the prize [5000] Cps & 10 EventPoint  for winning WeeklyPk-War  .", MsgServer.MsgMessage.ChatMode.Center, Game.MsgServer.MsgMessage.MsgColor.red);
                                client.Teleport(428, 378, 1002);
                            }
                        }
                        else
                        {
                            data.AddText("Top End in 21:06  And You Can Claim The Prize Only Between 21:06 To 21:20")
                                .AddOption("Thanks", 58)
                                .AddAvatar(63).FinalizeDialog();
                        }
                        break;
                    }
                case 25:
                    {
                        client.Teleport(428, 378, 1002);
                        client.Player.SetPkMode(DeathWish.Role.Flags.PKMode.Capture);


                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.WeeklyPK)]
        public static void WeeklyPK(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            DateTime Now64 = DateTime.Now;
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Hey " + client.Player.Name + " You Want to join Weekly Pk at Sunday 21:00 ?!");
                        if (Now64.DayOfWeek == DayOfWeek.Sunday && Now64.Hour == 21 && Now64.Minute >= 00 && Now64.Minute < 05)
                            data.AddOption("Weekly-Pk[Open] .", 30);
                        else
                            data.AddOption("Weekly-Pk[End] Start Sunday 21:00 .", 31);
                        data.AddOption("#Thanks .", 255).AddAvatar(80).FinalizeDialog();
                        break;
                    }

                case 30:
                    {
                        if (Now64.DayOfWeek == DayOfWeek.Sunday && Now64.Hour == 21 && Now64.Minute >= 00 && Now64.Minute < 05)
                            client.Teleport(124, 100, 1508);
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.SkillTournament)]
        public static void SkillTournament(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {

                        data.AddText("FB Or SS is a skill based for all event. Every player starts")
                          .AddText(" with 4 points. When hit fang your score is reduced by 1 point.")
               .AddText("When a player.s score reaches 0(they have been hit 5 times) they are eliminated ,The last persoan standing win, [ <tip color=0xff00fa00> " + " Start : Even :25" + " </tip> ].")
                           .AddOption("Join Eliminated-War", 1)
                           .AddOption("[---Sound---]", 2)
                 .AddOption("Thanks.", 255)
                 .AddAvatar(4).FinalizeDialog();

                        break;
                    }
                case 2:
                    {
                        client.Player.SendString(stream, MsgServer.MsgStringPacket.StringID.Sound, 0, false, "sound/Eliminate.wav", "1");
                        break;
                    }
                case 1:
                    {
                        if (client.Player.RightWeaponId != 0 && !client.Player.ContainFlag(MsgUpdate.Flags.PathOfShadow))
                        {
                            if (Game.MsgTournaments.MsgSchedules.CurrentTournament.Type == MsgTournaments.TournamentType.SkillTournament)
                            {
                                if (!Game.MsgTournaments.MsgSchedules.CurrentTournament.Join(client, stream))
                                {

                                    data.AddText("We are sorry , but u can't enter right now , try when tournament start !")
                                            .AddOption("I see. ", 255)
                                            .AddAvatar(63).FinalizeDialog();
                                }
                            }
                            else
                            {

                                data.AddText("We are sorry , but u can't enter right now , try when tournament start !")
                                     .AddOption("I see. ", 255)
                               .AddAvatar(63).FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry You Must Equip Any Weapon To Join Or If You Equip PathofShadow Remove It ")
                                 .AddOption("I see. ", 255)
                           .AddAvatar(63).FinalizeDialog();
                        }
                    }
                    break;
            }
        }

