        [NpcAttribute(NpcID.SeniorAssistant)]
        public static void SeniorAssistant(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            data.AddAvatar(148);
            switch (Option)
            {
                case 0:// quest item 711533
                    {
                        data.AddText("I'm CPS Changer , I'm here to help you get coins \n");

                        data.AddText("you can give me <tip color=0xff00fa00 >Cps</tip> To Get <tip color=0xff00fa00 >Coins</tip>  \n");
                        data.AddText("  The Rate of Change [ <tip color=0xff00fa00 > 100 CPs = 1 Coins </tip> ]\n ");
                        data.AddText("  Minimum Amout [ <tip color=0xff00fa00 > 10000 CPs </tip> ]\n ");
                        data.AddInput("Insert amount:", 1);
                        data.AddOption("ThankS", 255);
                        data.AddAvatar(9).FinalizeDialog();
                        break;
                    }

                case 1:
                    {
                        uint input;
                        if (uint.TryParse(Input, out input))
                        {
                            if (input < 10000)
                            {
                                data.AddText("You need to input more or atleast 10000 CPs..");
                                data.AddInput("Insert amount:", 1);
                                data.AddOption("ThankS", 255);
                                data.AddAvatar(48).FinalizeDialog();
                                return;
                            }
                            if (client.Player.ConquerPoints >= input)
                            {
                                client.NpcCpsInput = input;
                                data.AddText("Are you sure you want to Change " + input + " CPs? That means I will change it for you " + (((ulong)input) / 100) + " Coins .");
                                data.AddOption("Yes", 2);
                                data.AddOption("ThankS", 255);
                                data.AddAvatar(48).FinalizeDialog();
                            }
                            else
                            {
                                data.AddText("You don't have that much CPs. Try again. \nThe exchange ratio is 100:1. That means you give me 100  CPs, I  change it for you 1 Coins. The Maxmum amount is 10000 CPs.");
                                data.AddInput("Insert amount:", 1);
                                data.AddOption("ThankS", 255);
                                data.AddAvatar(48).FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Try again. \nThe exchange ratio is 100:1. That means you give me 100  CPs, I  change it for you 1 Coins. The minimum amount is 10000 CPs.");
                            data.AddInput("Insert amount:", 1);
                            data.AddOption("ThankS", 255);
                            data.AddAvatar(48).FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        if (client.Player.ConquerPoints >= client.NpcCpsInput && client.NpcCpsInput != 0)
                        {
                            client.Player.ConquerPoints -= (uint)client.NpcCpsInput;
                            client.Player.BoundConquerPoints += (int)client.NpcCpsInput / 100;
                            //data.AddText("");
                            client.Player.MessageBox("You Changed " + client.NpcCpsInput + " CPS To " + client.NpcCpsInput / 100 + " Coins ", null, null);
                            client.NpcCpsInput = 0;
                            client.Player.SendUpdate(stream, client.Player.ConquerPoints, MsgServer.MsgUpdate.DataType.ConquerPoints);
                            client.Player.SendUpdate(stream, client.Player.BoundConquerPoints, MsgServer.MsgUpdate.DataType.BoundConquerPoints);

                        }
                        break;
                    }


            }
        }
        [NpcAttribute(NpcID.PkReset)]
        public static void PkReset(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {

                        data.AddText("In exchange of 10 CPs per PK Point i will decrease your PK, do you think you are strong enough for this exchange?")
                           .AddOption("Clear 10 pkPoints.", 1)
                            .AddOption("Clear 100 pkPoints.", 2)
                             .AddOption("Clear 500 pkPoints.", 3)
                            .AddOption("Nevermind.", 255)
                              .AddAvatar(264)
                            .FinalizeDialog();

                        break;
                    }
                case 1:
                    {
                        if (client.Player.ConquerPoints >= 100)
                        {
                            if (client.Player.PKPoints >= 10)
                            {
                                client.Player.PKPoints -= 10;
                                client.Player.ConquerPoints -= 100;
                                client.Player.SendString(stream, MsgStringPacket.StringID.Effect, true, "eidolon");
                                client.CreateBoxDialog("You've removed 10 Pk Points.");
                            }
                            else
                            {
                                data.AddText("You can not use this option for now since your Pk points are less than 10.")
                                    .AddOption("I see.", 255)
                                      .AddAvatar(264)
                                    .FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry, but you don`t have enough CPs.")
                                     .AddOption("I see.", 255)
                                       .AddAvatar(264)
                                     .FinalizeDialog();
                        }

                        break;
                    }
                case 2:
                    {
                        if (client.Player.ConquerPoints >= 1000)
                        {
                            if (client.Player.PKPoints >= 100)
                            {
                                client.Player.PKPoints -= 100;
                                client.Player.ConquerPoints -= 1000;
                                client.CreateBoxDialog("You've removed 100 Pk Points.");
                                client.Player.SendString(stream, MsgStringPacket.StringID.Effect, true, "eidolon");
                            }
                            else
                            {
                                data.AddText("You can not use this option for now since your Pk points are less than 100.")
                                    .AddOption("I see.", 255)
                                      .AddAvatar(264)
                                    .FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry, but you don`t have enough CPs.")
                                     .AddOption("I see.", 255)
                                       .AddAvatar(264)
                                     .FinalizeDialog();
                        }

                        break;
                    }
                case 3:
                    {
                        if (client.Player.ConquerPoints >= 5000)
                        {
                            if (client.Player.PKPoints >= 500)
                            {
                                client.Player.PKPoints -= 500;
                                client.Player.ConquerPoints -= 5000;
                                client.CreateBoxDialog("You've removed 500 Pk Points.");
                                client.Player.SendString(stream, MsgStringPacket.StringID.Effect, true, "eidolon");
                            }
                            else
                            {
                                data.AddText("You can not use this option for now since your Pk points are less than 500.")
                                    .AddOption("I see.", 255)
                                      .AddAvatar(264)
                                    .FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry, but you don`t have enough CPs.")
                                     .AddOption("I see.", 255)
                                       .AddAvatar(264)
                                     .FinalizeDialog();
                        }

                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.GiftPackRetailer)]
        public static void GiftPackRetailer(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
