        [NpcAttribute(NpcID.Chhi)]
        public static void Chhi(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {

                        data.AddText("Choose The Type Which You Want Switch To it For 1M Cps  ..");
                        data.AddOption("[Chi] .", 5);
                        data.AddOption("#Thanks", 255);
                        data.AddAvatar(63).FinalizeDialog();
                        break;
                    }

                case 5:
                    {
                        if (client.Player.MyChi != null)
                        {
                            if (client.Player.MyChi.Dragon.Score == 367 && client.Player.MyChi.Phoenix.Score == 367 && client.Player.MyChi.Turtle.Score == 367 && client.Player.MyChi.Tiger.Score == 367)
                            {
                                data.AddText("Choose The Type Which You Want Switch To it For 500K Cps  ..");
                                data.AddOption("[Strike] .", 6);
                                data.AddOption("[Break] .", 8);
                                data.AddOption("#Thanks", 255);
                                data.AddAvatar(63).FinalizeDialog();
                            }
                            else
                            {
                                data.AddText("Sorry Bro You Must Upgrade Your Chi Score To 367 In Each Gate To Can Change It For 500k Cps  ..");
                                data.AddOption("#Thanks .", 255);
                                data.AddAvatar(63).FinalizeDialog();
                            }
                        }
                        break;
                    }
                case 6:
                    {
                        if (client.Player.ConquerPoints >= 500000)
                        {
                            client.Player.MyChi.Dragon.UnLocked = true;
                            if (!Role.Instance.Chi.ChiPool.ContainsKey(client.Player.UID))
                                Role.Instance.Chi.ChiPool.TryAdd(client.Player.UID, client.Player.MyChi);
                            client.Player.MyChi.Dragon.UID = client.Player.UID;
                            client.Player.MyChi.Dragon.Name = client.Player.Name;
                            client.Player.MyChi.Dragon.Reroll(Game.MsgServer.MsgChiInfo.LockedFlags.None);
                            Program.ChiRanking.Upadte(Program.ChiRanking.Dragon, client.Player.MyChi.Dragon);
                            client.Player.MyChi.Phoenix.UnLocked = true;
                            client.Player.MyChi.Tiger.UnLocked = true;
                            client.Player.MyChi.Turtle.UnLocked = true;
                            client.Player.ConquerPoints -= 500000;
                            var PowerType1 = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), "Dragon");
                            var Power1 = client.Player.MyChi.Where(p => p.Type == PowerType1).FirstOrDefault();
                            var PowerType2 = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), "Phoenix");
                            var Power2 = client.Player.MyChi.Where(p => p.Type == PowerType2).FirstOrDefault();
                            var PowerType3 = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), "Tiger");
                            var Power3 = client.Player.MyChi.Where(p => p.Type == PowerType3).FirstOrDefault();
                            var PowerType4 = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), "Turtle");
                            var Power4 = client.Player.MyChi.Where(p => p.Type == PowerType4).FirstOrDefault();


                            var attribte = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), "CriticalStrike");
                            var mr7la = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), "Immunity");
                            var mr7lak = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), "MaxLife");
                            var mr7lakz = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), "AddAttack");
                            var Value = Role.Instance.Chi.MaxPower(attribte);
                            var Valuee = Role.Instance.Chi.MaxPower(mr7la);
                            var Valueee = Role.Instance.Chi.MaxPower(mr7lak);
                            var Valueeee = Role.Instance.Chi.MaxPower(mr7lakz);

                            Power1.Fields[0] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                            Power1.Fields[1] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7la, (int)((byte)mr7la * 10000 + Valuee));
                            Power1.Fields[2] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lak, (int)((byte)mr7lak * 10000 + Valueee));
                            Power1.Fields[3] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lakz, (int)((byte)mr7lakz * 10000 + Valueeee));
                            Power2.Fields[0] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                            Power2.Fields[1] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7la, (int)((byte)mr7la * 10000 + Valuee));
                            Power2.Fields[2] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lak, (int)((byte)mr7lak * 10000 + Valueee));
                            Power2.Fields[3] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lakz, (int)((byte)mr7lakz * 10000 + Valueeee));
                            Power3.Fields[0] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                            Power3.Fields[1] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7la, (int)((byte)mr7la * 10000 + Valuee));
                            Power3.Fields[2] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lak, (int)((byte)mr7lak * 10000 + Valueee));
                            Power3.Fields[3] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lakz, (int)((byte)mr7lakz * 10000 + Valueeee));
                            Power4.Fields[0] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                            Power4.Fields[1] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7la, (int)((byte)mr7la * 10000 + Valuee));
                            Power4.Fields[2] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lak, (int)((byte)mr7lak * 10000 + Valueee));
                            Power4.Fields[3] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lakz, (int)((byte)mr7lakz * 10000 + Valueeee));
                        }
                        else
                        {
                            data.AddText("Sorry you don`t have 500k  cps.")
                         .AddOption("I~see.", 255)
                         .AddAvatar(123).FinalizeDialog();
                            break;
                        }
                        client.Socket.Disconnect();
                        break;
                    }
                case 8:
                    {
                        if (client.Player.ConquerPoints >= 500000)
                        {
                            client.Player.MyChi.Dragon.UnLocked = true;
                            if (!Role.Instance.Chi.ChiPool.ContainsKey(client.Player.UID))
                                Role.Instance.Chi.ChiPool.TryAdd(client.Player.UID, client.Player.MyChi);
                            client.Player.MyChi.Dragon.UID = client.Player.UID;
                            client.Player.MyChi.Dragon.Name = client.Player.Name;
                            client.Player.MyChi.Dragon.Reroll(Game.MsgServer.MsgChiInfo.LockedFlags.None);
                            Program.ChiRanking.Upadte(Program.ChiRanking.Dragon, client.Player.MyChi.Dragon);
                            client.Player.MyChi.Phoenix.UnLocked = true;
                            client.Player.MyChi.Tiger.UnLocked = true;
                            client.Player.MyChi.Turtle.UnLocked = true;
                            client.Player.ConquerPoints -= 500000;
                            var PowerType1 = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), "Dragon");
                            var Power1 = client.Player.MyChi.Where(p => p.Type == PowerType1).FirstOrDefault();
                            var PowerType2 = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), "Phoenix");
                            var Power2 = client.Player.MyChi.Where(p => p.Type == PowerType2).FirstOrDefault();
                            var PowerType3 = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), "Tiger");
                            var Power3 = client.Player.MyChi.Where(p => p.Type == PowerType3).FirstOrDefault();
                            var PowerType4 = (Game.MsgServer.MsgChiInfo.ChiPowerType)Enum.Parse(typeof(Game.MsgServer.MsgChiInfo.ChiPowerType), "Turtle");
                            var Power4 = client.Player.MyChi.Where(p => p.Type == PowerType4).FirstOrDefault();


                            var attribte = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), "Breakthrough");
                            var mr7la = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), "Immunity");
                            var mr7lak = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), "MaxLife");
                            var mr7lakz = (Role.Instance.Chi.ChiAttributeType)Enum.Parse(typeof(Role.Instance.Chi.ChiAttributeType), "AddAttack");
                            var Value = Role.Instance.Chi.MaxPower(attribte);
                            var Valuee = Role.Instance.Chi.MaxPower(mr7la);
                            var Valueee = Role.Instance.Chi.MaxPower(mr7lak);
                            var Valueeee = Role.Instance.Chi.MaxPower(mr7lakz);

                            Power1.Fields[0] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                            Power1.Fields[1] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7la, (int)((byte)mr7la * 10000 + Valuee));
                            Power1.Fields[2] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lak, (int)((byte)mr7lak * 10000 + Valueee));
                            Power1.Fields[3] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lakz, (int)((byte)mr7lakz * 10000 + Valueeee));
                            Power2.Fields[0] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                            Power2.Fields[1] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7la, (int)((byte)mr7la * 10000 + Valuee));
                            Power2.Fields[2] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lak, (int)((byte)mr7lak * 10000 + Valueee));
                            Power2.Fields[3] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lakz, (int)((byte)mr7lakz * 10000 + Valueeee));
                            Power3.Fields[0] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                            Power3.Fields[1] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7la, (int)((byte)mr7la * 10000 + Valuee));
                            Power3.Fields[2] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lak, (int)((byte)mr7lak * 10000 + Valueee));
                            Power3.Fields[3] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lakz, (int)((byte)mr7lakz * 10000 + Valueeee));
                            Power4.Fields[0] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)attribte, (int)((byte)attribte * 10000 + Value));
                            Power4.Fields[1] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7la, (int)((byte)mr7la * 10000 + Valuee));
                            Power4.Fields[2] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lak, (int)((byte)mr7lak * 10000 + Valueee));
                            Power4.Fields[3] = Tuple.Create((Role.Instance.Chi.ChiAttributeType)mr7lakz, (int)((byte)mr7lakz * 10000 + Valueeee));
                        }
                        else
                        {
                            data.AddText("Sorry you don`t have 500k cps.")
                         .AddOption("I~see.", 255)
                         .AddAvatar(123).FinalizeDialog();
                            break;
                        }
                        client.Socket.Disconnect();
                        break;
