                            data.AddText("Your inventory is full! Please make 2 cells first before you claim the reward!");
                            data.AddOption("Okay.", 255);
                            data.AddAvatar(31);
                            data.FinalizeDialog();
                        }
                        break;
                    }
                case 2:
                    {
                        if (client.Player.DefeatedArenaGuardians >= 30)
                        {
                            client.Player.DefeatedArenaGuardians -= 30;
                            client.GainExpBall(600);
                            client.Player.SendString(stream, MsgStringPacket.StringID.Effect, false, "angelwing");
                            client.SendSysMesage("You have claimed experience worth an Exp Ball!", MsgMessage.ChatMode.System);
                        }
                        else
                        {
                            data.AddText("You need to defeat 30 guardians first to claim experience from the Agate.");
                            data.AddOption("Okay.", 255);
                            data.FinalizeDialog();
                        }
                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.ArenaManagerWang)]
        public static void ArenaManagerWang(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        //action = 5003620
                        if (MsgTournaments.MsgSchedules.PowerArena.Process == MsgTournaments.ProcesType.Alive)
                        {
                            data.AddText("Would you like to test your power and skill in the Power Arena? The challenge is under way. Jump in now!");
                            data.AddOption("Enter~Arena.", 30);
                            data.AddOption("What`s~are~the~rules?", 20);
                            data.AddOption("Exchange~for~refinery~packs.", 10);
                            data.AddOption("Not~interested!", 255);
                            data.AddAvatar(31);
                            data.FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("Want to test your power and skill? Power Arena has now provided you such a chance. Come to Arena Manager Wang between 13:00 pm and 14:00pm or 20:00 pm and 20:59 pm to accept the challenge!");
                            data.AddOption("I~will~be~there!", 255);
                            data.AddOption("Exchange~for~refinery~packs.", 10);
                            data.AddOption("Rules?", 20);
                            data.AddAvatar(31);
                            data.FinalizeDialog();
                        }
                        break;
                    }
                case 30:
                    {
                        //if (MsgTournaments.MsgSchedules.PowerArena.Process == MsgTournaments.ProcesType.Alive)
                        {
