                        {
                            data.AddText("HELP! HELP! Could you help me out?")
                             .AddOption("What`s~wrong?", 1).AddAvatar(67)
                                .FinalizeDialog();
                            break;
                        }
                        else if (client.Player.QuestGUI.CheckQuest(ActiveQuest2.MissionId, MsgQuestList.QuestListItem.QuestStatus.Finished) == false)
