                    {
                        data.AddText("I heard that General Yue, the great hero, was the incarnation of a Golden Roc. Is it possible that Poor Xiao is his descendent?");
                        data.AddOption("What?!", 41);
                        data.AddAvatar(67);
                        data.FinalizeDialog();
