                           .AddOption("Sorry~but~I`m~busy.", 255).AddAvatar(35).FinalizeDialog();
                        break;
                    }
                case 42:
                    {
                        client.CreateBoxDialog("Collect~the~items~which~stand~for~the~gold,~water,~wood~and~fire~elements.");
