                case 1:
                    {
                        data.AddText("You seem curious about the box. Would you like to open it?")
                                                      .AddOption("Yeah,~yeah.", 2)
                                                      .AddOption("No~need.", 255)
                                                      .AddAvatar(67).FinalizeDialog();
                        break;
