                    {
                        client.Player.QuestGUI.Accept(ActiveQuest, 0);
                        data.AddText("The box is locked and you can`t open it. Why not ask Ximen Qing? Maybe he knows something.")
                                                      .AddOption("Okay.", 255)
                                                      .AddAvatar(67).FinalizeDialog();
                        break;
