                            .AddText("~The first thing I need to do is finish the kite. Could you please collect 5 feathers from the BirdmenL88 that are outside?")
                                        .AddOption("Ok.", 11)
                                        .AddOption("I`ll~think~about.", 255)
                                        .AddAvatar(35).FinalizeDialog();
                        break;
                    }
