                    {
                        client.CreateBoxDialog("Kill~the~BirdmanL88~to~collect~5~feathers.");
                        client.Player.QuestGUI.Accept(ActiveQuest2, 0);
                        break;

                    }
                case 1:
                    {
                        if (client.Player.QuestGUI.CheckObjectives(ActiveQuest.MissionId, 20))
