                            data.AddText("My wife is always being too careful... And I thought my mother was overprotective! Anyway, thanks for your help!")
                                                      .AddOption("You`re~welcome.", 255)
                                                      .AddAvatar(35).FinalizeDialog();
                        }
                        else
