                            }
                            else
                            {
                                data.AddText("The Sand Monsters must have something to do with the weird yellow sand. I need you to turn to the Sand Monsters for some clues.")
                      .AddOption("Alright.", 255)
                      .AddAvatar(51).FinalizeDialog();
                            }
                            break;
