                                .AddOption("No.", 255)

                                .AddAvatar(116).FinalizeDialog();
                            client.Player.QuestGUI.Accept(ActiveQuest2, 0);
                        }

                        break;
                    }
                case 4:
                    {
                        client.Player.QuestGUI.SendAutoPatcher(1011, 48, 381, 0);
                        break;
