                case 7:
                    {
                        if (!client.Inventory.HaveSpace(3))
                        {
                            data.AddText("Please make 3 more spaces in your inventory.")
                             .AddOption("let me check.", 255)
                             .AddAvatar(116).FinalizeDialog();
