        [NpcAttribute(NpcID.BattleFieldMain)]
        public static void BattleFieldMain(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);

            switch (Option)
            {
                case 0:
                    {
                        data.AddText(" HORUS-Event takes place Every day at [ <tip color=0xff00fa00> " + " 20:00 --To-- 20:20 " + " </tip> ] . If you want to prove youself in the Main Event , come to see me at that time.");
                        data.AddText(" When Join The Event You Must Kill Monsters To Get More points When The Event End Your Point Exchange With Cps Ans There Are [ <tip color=0xff00fa00> " + " Special Reward To Top 3 " + " </tip> ] ");
                        if (DateTime.Now.Hour == 20 && DateTime.Now.Minute >= 00 && DateTime.Now.Minute < 20)
                        {
                            data.AddOption("Join.", 2);
                            //   data.AddOption("[---Sound---]", 4)
                            data.AddOption("Thanks.", 255);
                            data.AddAvatar(4).FinalizeDialog();
                        }
                        else
                        {
                            data.AddOption("Ranking.", 1);
                            data.AddOption("Reward. ", 3);
                           // data.AddOption("[---Sound---]", 4);
                            data.AddOption("Thanks. ", 255);
                            data.AddAvatar(4).FinalizeDialog();
                        }

                        break;
                    }
                case 1:
                    {
                        data.AddText("                                  <tip color=0xff00fa00> " + "  HORUS-Event Top 3 " + " </tip>       \n");
                        var tournament = (Game.MsgTournaments.MsgSchedules.Tournaments[MsgTournaments.TournamentType.BattleField] as Game.MsgTournaments.MsgBattleField);
                        int count = 1;
                        foreach (var user in tournament.Rank3)
                        {
                            data.AddText(" [ <tip color=0xff00fa00> " + " Rank " + " </tip> ] [ <tip color=0xff00fa00> " + count.ToString() + " </tip> ]  is--- " + user.Name + " --- Score   [ <tip color=0xff00fa00> " + user.BattlePoints.ToString() + " </tip> ] Points. \n");
                            count++;
                        }
                        data.AddOption("Okay.", 255)
                .AddAvatar(63).FinalizeDialog();


                        break;
                    }
                case 4:
                    {
                        client.Player.SendString(stream, MsgServer.MsgStringPacket.StringID.Sound, 0, false, "sound/MainEvent.wav", "1");
                        break;
                    }
                case 2:
                    {
                        if (!client.Player.OnTransform)
                        {
                            if (DateTime.Now.Hour == 20 && DateTime.Now.Minute >= 00 && DateTime.Now.Minute < 20)
                            {
                                client.Player.BattleFieldPoints = 0;
                                client.Teleport(250, 250, 3030);
                            }
                            else
                            {
                                data.AddText("We are sorry , but u can't enter right now , try when tournament start !")
     .AddOption("Okay.", 255)
     .AddAvatar(63).FinalizeDialog();
                            }

                        }
                        else
                        {
                            data.AddText("We are sorry , but u can't enter While You Use DivineHare!")
 .AddOption("Okay.", 255)
 .AddAvatar(63).FinalizeDialog();
                        }
                        break;
                    }
                case 3:
                    {
                        data.AddText("Are you One of Top Players: \n");
                        var tournament = (Game.MsgTournaments.MsgSchedules.Tournaments[MsgTournaments.TournamentType.BattleField] as Game.MsgTournaments.MsgBattleField);
                        int count = 1;
                        foreach (var user in tournament.Rank3)
                        {
                            data.AddText(" [ <tip color=0xff00fa00> " + " Rank " + " </tip> ] [ <tip color=0xff00fa00> " + count.ToString() + " </tip> ]  is--- " + user.Name + " ---. \n");
                            count++;
                        }
                        data.AddOption("I`m Sure.", 5)
                            .AddOption("No.Thanks.", 255)
                .AddAvatar(63).FinalizeDialog();

                        break;
                    }
                case 5:
                    {
                        var tournament = (Game.MsgTournaments.MsgSchedules.Tournaments[MsgTournaments.TournamentType.BattleField] as Game.MsgTournaments.MsgBattleField);
                        foreach (var user in tournament.Rank3)
                        {
                            if (user.Name == client.Player.Name && client.Player.BattleFieldPoints > 0)
                            {
                                Program.SendGlobalPackets.Enqueue(new Game.MsgServer.MsgMessage(client.Player.Name + " Claimed [Great Reward for Soul P7 + 100 Coins + 23H Attack[Cup] + 23 H Germent + 23 H Mount] .! From Top-3 HORUS-Event", Game.MsgServer.MsgMessage.MsgColor.yellow, Game.MsgServer.MsgMessage.ChatMode.System).GetArray(stream));
                                client.Inventory.AddItemWitchStack(3004244, 0, 1, stream);
                                client.Inventory.AddItemWitchStack(3004245, 0, 1, stream);
                                client.Inventory.AddItemWitchStack(3004243, 0, 1, stream);
                                client.Player.BoundConquerPoints += 100;
                                client.Inventory.AddDIABLO2(2100085, 1, 1, stream, true, 0, 23, 0);//CupTime 
                                client.Inventory.AddDIABLO2(194175, 1, 1, stream, true, 0, 23, 0);//Germent time
                                client.Inventory.AddDIABLO2(200993, 1, 1, stream, true, 0, 23, 0);//Mount time                                                                    
                                client.CreateBoxDialog("You Have Get Top 3 Reward   Great Reward for Soul P7 + 100 Coins + 23H Attack[Cup] + 23 H Germent + 23 H Mount]  ");
                                client.Player.BattleFieldPoints = 0;
                                return;
                            }

                        }
                        data.AddText("Sorry You are not Listed in Top 3  Or you Claimed The Rewerad. Come back when you are Ranked")
                              .AddOption("Thanks.", 255)
                              .AddAvatar(63)
                              .FinalizeDialog();
                        break;
                    }
            }
        }
