        [NpcAttribute(NpcID.SkillTeamPkManager)]
        public static void SkillTeamPkManager(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
