        [NpcAttribute(NpcID.EXPIKA)]
        public static void EXPIKA(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("There`s a mysterious treasure sealed since the ancient times. You Can Exchange Your Event Points To DIABLO[T]                                                                ")
                            .AddText(" You Can Exchange You----Your Event Points [ <tip color=0xff00fa00> " + client.Player.PIKAPoint + " </tip> ]  .")
                            .AddOption("1 DIABLO[T] [2 Point].", 1)
                            .AddOption("5 DIABLO[T] [9 Point].", 2)
                            .AddOption("10 DIABLO[T] [18 Point].", 3)
                    .AddOption("Thanks.", 255)
                     .AddAvatar(200)
                    .FinalizeDialog();


                        break;
                    }
                case 1:
                    {
                        if (client.Player.PIKAPoint >= 2)
                        {
                            client.Player.PIKAPoint -= 2;
                            client.Inventory.Add(stream, 3005544);
                            client.CreateBoxDialog("You received a 1 DIABLO[T].");

                        }
                        else
                        {
                            data.AddText("You Don`t Have 2 Event Points.")
                            .AddOption("OK.Thanks.", 255).FinalizeDialog();
                        }
