        {
            var ActiveQuest = Database.QuestInfo.GetFinishQuest((uint)NpcID.Pharmacist, client.Player.Class, 815);
            var ActiveQuest2 = Database.QuestInfo.GetFinishQuest((uint)id, client.Player.Class);
