                                    data.AddText("You have reahced the highest BP Bonus Level and the members can share 70 percent of the Battle Power margin in the same map.");
                                    data.AddOption("Sounds~good!");
                                    data.AddAvatar(39);
                                    data.FinalizeDialog();
                                }
                            }
                            else
