                                    case 2: client.Teleport(47, 47, 26397); break; //Monk Boss
                                    case 3: client.Teleport(47, 47, 26394); break; //Trojan Boss
                                    case 4: client.Teleport(47, 47, 26398); break; //Assisan Boss
                                    case 5: client.Teleport(47, 47, 26391); break; //WindWalker Boss
                                    case 6: client.Teleport(47, 47, 26395); break; //Archer Boss
                                    case 7: client.Teleport(47, 47, 26399); break; //Pirate Boss
                                    case 8: client.Teleport(47, 47, 26396); break; //DragonWarrior Boss
                                    case 9: client.Teleport(47, 47, 26393); break; //Fire Boss

                                }
                            }
                            else
                            {
                                data.AddText("Hey! You don't have 100 gold do you?\nDon't you dare try to cheat me or I'll call the guards!")
                             .AddOption("Crazy!", 255)
                             .AddAvatar(10)
                             .FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("I will not help MURDERS!")
                           .AddOption("Okay...", 255)
                            .AddAvatar(10)
                           .FinalizeDialog();

                        }



                        break;
                    }
            }
        }
        [NpcAttribute(NpcID.DragonWar)]
        public static void DragonWar(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);

            switch (Option)
            {
                case 0:
                    {
                        data.AddText("In Dragon war you  only use FB/SS. One Player will become the ")
                        .AddText("DragonKing causing them to gain points per secound. 1 shot enemies and gain ")
                        .AddText("points per kill. The dragon king will die in 3 hits and the person who slays ")
                        .AddText("him will become the new DragonKing! [ <tip color=0xff00fa00> " + " Start : xx :25" + " </tip> ].")
                           .AddOption("Join-DragonWar", 1)
                             .AddOption("[---Sound---]", 2)
                          .AddOption("Thanks.", 255)
                         .AddAvatar(4).FinalizeDialog();

                        break;
                    }
                case 2:
                    {
                        client.Player.SendString(stream, MsgServer.MsgStringPacket.StringID.Sound, 0, false, "sound/DRAGON.wav", "1");
                        break;
                    }
                case 1:
                    {
                        if (client.Player.RightWeaponId != 0 && !client.Player.ContainFlag(MsgUpdate.Flags.PathOfShadow))
                        {
                            if (Game.MsgTournaments.MsgSchedules.CurrentTournament.Type == MsgTournaments.TournamentType.DragonWar)
                            {
                                if (!Game.MsgTournaments.MsgSchedules.CurrentTournament.Join(client, stream))
                                {
                                    data.AddText("We are sorry , but u can't enter right now , try when tournament start !")
                                    .AddOption("I see. ", 255)
                                    .AddAvatar(63).FinalizeDialog();
                                }
                            }
                            else
                            {
                                data.AddText("We are sorry , but u can't enter right now , try when tournament start !")
                                .AddOption("I see. ", 255)
                                .AddAvatar(63).FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("Sorry.You Must Equip Any Weapon To Join Or If You Equip PathOfShadow Remove It ")
                             .AddOption("I see. ", 255)
                            .AddAvatar(63).FinalizeDialog();
                        }


                    }
                    break;

            }



        }

        [NpcAttribute(NpcID.TwinCityConductress)]
        public static void TwinCityConductress(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    {
                        data.AddText("Where~are~you~heading~for?~I~can~teleport~you~for~a~price~of~100~silver.")
                        .AddOption("Phoenix Castle.", 1)
                        .AddOption("Ape City.", 2)
                        .AddOption("Desert City.", 3)
                        .AddOption("Bird Island.", 4)
                        .AddOption("Mine Cave.", 5)
                        .AddOption("Market.", 6)
                            // .AddOption("Dragon Island.", 7)
                       .AddOption("Just~passing~by.", 255).AddAvatar(10).FinalizeDialog();


                        break;
                    }
                default:
                    {
                        if (client.Player.Money >= 100)
                        {
                            client.Player.Money -= 100;
                            client.Player.SendUpdate(stream, client.Player.Money, MsgServer.MsgUpdate.DataType.Money);
                            switch (Option)
                            {
                                case 1: client.Teleport(958, 555, 1002); break; //phoenix castle
                                case 2: client.Teleport(555, 957, 1002); break; //ape mountain
                                case 3: client.Teleport(69, 473, 1002); break; //desert city
                                case 4: client.Teleport(232, 190, 1002); break; //birdisland
                                case 5: client.Teleport(53, 399, 1002); break; // Mine Cave
                                case 6: client.Teleport(217, 198, 1036); break; //market
                                case 7: client.Teleport(547, 370, 1002); break; //dragon island

                            }
                        }
                        else
                        {
                            data.AddText("Hey! You don't have 100 gold do you?\nDon't you dare try to cheat me or I'll call the guards!")
                         .AddOption("Crazy!", 255)
                         .AddAvatar(10)
                         .FinalizeDialog();
                        }

                        break;
                    }
            }
        }


        [NpcAttribute(NpcID.BlackSmith)]
        public static void BlackSmith(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            var ActiveQuest = Database.QuestInfo.GetFinishQuest((uint)NpcID.WHTwin, client.Player.Class);
            var ActiveQuest2 = Database.QuestInfo.GetFinishQuest((uint)id, client.Player.Class, 823);
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {

                case 0:
                    {
                        if (client.Player.QuestGUI.IsActiveQuest(ActiveQuest.MissionId))
                        {
                            data.AddText("Ahh, Warehouseman asked you here, huh? Yeah, you are in the right place! You know, weapons are the most important things in battle. Even the toughest warriors can`t survive without a weapon in their hands!")
